(window.TNQ=window.TNQ||[]).push({"terms":{"동기의 착오":{"d":"법률행위의 직접 내용이 아니라 의사를 결정한 이유나 동기를 잘못 안 경우예요. 표시되어 내용이 되면 취소 사유가 돼요.","r":[]},"사정변경":{"d":"계약 성립의 기초가 된 사정이 현저히 변해 계약을 해제하거나 해지할 수 있게 하는 법리이다.","r":[]},"통정허위표시":{"d":"상대방과 짜고 진의 없이 하는 허위의 의사표시로 무효이다.","r":[]},"복대리인":{"d":"대리인이 자기 이름으로 선임해 본인을 대리하게 하는 하위 대리인이에요.","r":["표현대리"]},"표현대리":{"d":"대리권이 없는데도 본인의 책임 있는 사정으로 대리권이 있는 것처럼 보이는 경우 본인이 책임지는 제도이다.","r":[]},"불확정기한":{"d":"도래하는 것은 확실하나 도래 시기를 알 수 없는 기한이다.","r":[]},"정지조건":{"d":"조건이 성취되어야 법률행위의 효력이 생기는 조건이다.","r":[]},"무효행위 전환":{"d":"무효인 법률행위가 다른 법률행위로서 요건을 갖추면 그 효력을 인정하는 제도예요.","r":[]},"묵시적 추인":{"d":"명시적 표시 없이 무효임을 알면서 효과를 자기에게 돌리려는 행동으로 추인한 것으로 보는 경우예요.","r":[]},"소멸시효":{"d":"권리자가 일정 기간 권리를 행사하지 않으면 그 권리가 소멸하는 제도이다.","r":[]},"제척기간":{"d":"권리의 존속기간으로, 중단이 없고 법원이 직권으로 조사한다.","r":[]},"출소기간":{"d":"그 기간 안에 반드시 소를 제기해야 하는 제척기간이에요.","r":["제척기간"]},"가등기":{"d":"본등기에 필요한 요건이 갖춰지지 않을 때 장래의 본등기의 순위를 보전하기 위해 하는 예비 등기이다.","r":[]},"진정명의회복":{"d":"등기명의가 잘못된 경우 말소 대신 진정한 소유자에게 소유권이전등기를 청구해 명의를 회복하는 방법이다.","r":[]},"원시취득":{"d":"다른 사람의 권리와 관계없이 처음으로 권리를 취득하는 것이에요.","r":[]},"방해배제청구권":{"d":"소유물에 대한 방해를 제거해 달라고 청구하는 물권적 청구권이다.","r":[]},"선의취득":{"d":"무권리자로부터 동산을 평온·공연하게 선의·무과실로 거래하여 취득하면 소유권을 얻는 제도이다.","r":[]},"혼동":{"d":"소유권과 다른 물권 등이 한 사람에게 모이면 다른 물권이 소멸하는 일이에요.","r":[]},"합유":{"d":"조합원이 조합재산을 공동으로 소유하는 형태로, 지분의 단독 처분이 제한된다.","r":[]},"총유":{"d":"비법인사단의 구성원이 재산을 관리·처분은 단체적으로 하고 사용·수익은 개별적으로 하는 공동소유 형태이다.","r":[]},"자주점유":{"d":"소유의 의사를 가지고 하는 점유로, 점유의 권원이나 객관적 사정에 따라 판단한다.","r":[]},"부합":{"d":"소유자가 다른 물건이 결합해 한 물건처럼 되어 소유권이 한 사람에게 귀속되는 현상이에요.","r":[]},"명의신탁":{"d":"실제 권리자가 부동산 등기 등을 타인의 이름으로 두는 약정으로, 부동산실명법상 무효이다.","r":[]},"담보지상권":{"d":"토지의 담보가치를 보전하려고 근저당권과 함께 설정하는 지상권이다.","r":[]},"법정지상권":{"d":"토지와 건물의 소유자가 달라질 때 법률 규정에 따라 건물 소유자가 갖게 되는 지상권이다.","r":[]},"분묘기지권":{"d":"타인 토지에 분묘를 설치한 사람이 그 기지를 사용할 수 있는 관습상 물권이다.","r":[]},"주위토지통행권":{"d":"공로에 통할 수 없는 토지의 소유자가 주위의 토지를 통행할 수 있는 권리이다.","r":[]},"유치권":{"d":"타인의 물건을 점유한 자가 그 물건에 관해 생긴 채권을 변제받을 때까지 유치하는 법정담보물권이다.","r":[]},"근저당권":{"d":"계속적 거래에서 생기는 불특정 채권을 채권최고액 한도에서 담보하는 저당권이다.","r":[]},"물상보증인":{"d":"다른 사람의 채무를 위해 자기 재산을 담보로 제공한 사람이에요.","r":[]},"변제자대위":{"d":"제3자나 보증인이 채무를 갚으면 채권자의 권리를 대신 행사할 수 있게 되는 제도예요.","r":[]},"사해행위":{"d":"채무자가 채권자를 해함을 알면서 재산을 감소시키는 법률행위이다.","r":[]},"지연손해금":{"d":"금전채무를 제때 갚지 않아 생긴 손해를 배상하는 금액으로, 채무 이행이 늦은 기간 동안 쌓여요.","r":[]},"손해배상액 예정":{"d":"채무불이행에 대비해 미리 배상할 금액을 약정해 두는 것이에요.","r":[]},"지명채권":{"d":"채권자가 특정되어 있어 양도하려면 통지나 승낙이 필요한 보통의 채권이에요.","r":[]},"면책적 채무인수":{"d":"제3자가 채무를 인수하고 종래 채무자는 채무에서 벗어나는 계약이다.","r":[]},"부진정연대채무":{"d":"여러 채무자가 같은 급부를 목적으로 각자 전부를 이행할 의무가 있으나 주관적 공동관계가 없는 채무이다.","r":[]},"자동채권":{"d":"상계하는 사람이 가진 채권으로, 상대방에게 청구하는 쪽의 채권이다.","r":[]},"합의해제":{"d":"계약 당사자가 다시 합의해서 계약을 없애는 일이에요. 해제권 행사와 달라요.","r":[]},"해약금":{"d":"계약금을 교부한 자는 이를 포기하고, 수령한 자는 배액을 상환해 계약을 해제할 수 있는 금전이다.","r":[]},"동시이행":{"d":"쌍무계약에서 상대방이 이행을 제공할 때까지 자기 채무의 이행을 거절할 수 있는 항변권이에요.","r":[]},"사용자책임":{"d":"피용자가 업무 집행 중 남에게 입힌 손해를 사용자가 배상하는 책임이에요.","r":[]},"공동불법행위":{"d":"여러 사람이 공동으로 불법행위를 하여 손해를 입힌 경우로, 연대하여 배상한다.","r":[]},"과실상계":{"d":"손해 발생에 피해자의 과실이 있을 때 손해배상액을 줄이는 제도이다.","r":[]},"사무관리":{"d":"의무 없이 타인을 위해 그의 사무를 관리하는 행위로, 법정채권관계가 생긴다.","r":[]},"부당이득":{"d":"법률상 원인 없이 타인의 재산이나 노무로 이익을 얻고 타인에게 손해를 입히는 것이다.","r":[]},"재산분할청구권":{"d":"이혼한 부부 한쪽이 혼인 중 쌓은 재산의 분할을 상대방에게 청구하는 권리예요.","r":[]},"유책배우자":{"d":"혼인이 깨지게 된 주된 책임이 있는 배우자예요.","r":[]},"친생추정":{"d":"혼인 중 아내가 임신한 자녀를 남편의 자녀로 추정하는 제도예요.","r":["친생부인의 소"]},"친생부인의 소":{"d":"법률상 부의 친생자 추정을 깨기 위해 제기하는 소이다.","r":[]},"친양자":{"d":"친생부모와의 친족관계를 끊고 양부모의 친생자와 같은 지위를 갖게 되는 양자이다.","r":[]},"상속회복청구권":{"d":"진정한 상속인이 상속권을 침해당했을 때 그 회복을 청구하는 권리예요.","r":["참칭상속인"]},"참칭상속인":{"d":"상속인이 아니면서 상속인이라고 믿게 하는 외관을 갖추거나 상속재산을 점유하는 사람이에요.","r":["상속회복청구권"]},"한정승인":{"d":"상속으로 얻은 재산 한도 안에서만 피상속인의 채무를 갚겠다는 승인이에요.","r":[]},"유류분":{"d":"상속인이 피상속인의 유언이나 증여와 관계없이 법으로 보장받는 최소한의 상속분이에요.","r":[]},"기여분":{"d":"공동상속인 중 피상속인의 재산 유지·증가에 특별히 기여한 사람에게 더 얹어 주는 상속분이에요.","r":[]},"협의이혼":{"d":"부부가 합의하여 가정법원의 확인을 받고 신고함으로써 하는 이혼이다.","r":[]},"친권자":{"d":"미성년 자녀를 보호하고 교양하며 재산을 관리하는 권리와 의무를 지는 사람이에요.","r":[]},"가족관계등록부":{"d":"가족관계의 발생과 변동을 개인별로 기록하는 공적 장부로, 가족관계의 등록 등에 관한 법률에 따라 작성된다.","r":[]},"등록기준지":{"d":"가족관계등록부를 편제하는 기준이 되는 장소로, 본인이 정하며 변경 신고를 할 수 있다.","r":[]},"친생자":{"d":"혼인 관계에서 태어난 자녀 등 법률상 친자관계가 인정되는 자녀이다.","r":[]},"친생자 추정":{"d":"민법에 따라 혼인 중 아내가 임신한 자녀를 남편의 자녀로 법률상 추정하는 제도이다.","r":[]},"인지":{"d":"혼인 외의 출생자를 생부나 생모가 자기 자녀로 인정하는 행위이다.","r":[]},"파양":{"d":"입양으로 맺어진 양친자관계를 해소하는 것이다.","r":[]},"보고적 신고":{"d":"이미 발생한 사실이나 법률관계를 보고하는 신고로, 출생·사망신고가 해당한다.","r":[]},"특정등록사항":{"d":"가족관계등록부에서 성명, 성별, 출생연월일, 주민등록번호 등 본인을 특정하는 기록 사항이다.","r":[]},"일반등록사항":{"d":"가족관계등록부에서 특정등록사항 외의 변동 사유 등을 기록하는 사항이다.","r":[]},"등록사항별 증명서":{"d":"가족관계증명서, 혼인관계증명서 등 등록부 기록을 사항별로 증명하는 서면이다.","r":[]},"상세증명서":{"d":"등록사항별 증명서 중 과거의 기록과 사유까지 모두 보여 주는 증명서이다.","r":[]},"특정증명서":{"d":"신청인이 선택한 일부 사항만 현출해 증명하는 증명서이다.","r":[]},"가족관계등록창설":{"d":"등록부가 없는 사람을 위해 법원의 허가를 받아 새로 등록부를 만드는 것이다.","r":[]},"등록부정정":{"d":"가족관계등록부의 기록이 잘못되었을 때 법원의 허가 등을 받아 바로잡는 절차이다.","r":[]},"이중등록부":{"d":"동일인에 대해 가족관계등록부가 둘 이상 작성된 경우를 가리킨다.","r":[]},"비송사건":{"d":"소송이 아닌 법원의 후견적 절차로 처리되는 사건으로 가족관계등록 허가 사건 등이 해당한다.","r":[]},"재산분할":{"d":"이혼한 부부가 혼인 중 함께 이룬 재산을 나누는 제도이다.","r":[]},"위자료":{"d":"상대방의 유책행위로 입은 정신적 고통에 대한 손해배상금이다.","r":[]},"양육비":{"d":"이혼 후 자녀를 양육하는 데 드는 비용으로, 양육하지 않는 부모가 분담한다.","r":[]},"사실혼":{"d":"혼인신고는 하지 않았지만 부부로서 공동생활을 하는 실질적 혼인관계이다.","r":[]},"중혼":{"d":"배우자가 있는 사람이 다시 혼인하는 것이다.","r":[]},"일신전속권":{"d":"권리자 한 사람에게만 속해 양도나 상속이 되지 않는 권리이다.","r":[]},"성년후견":{"d":"정신적 제약으로 사무 처리 능력이 지속적으로 결여된 사람을 위해 후견인을 두는 제도이다.","r":[]},"한정후견":{"d":"사무 처리 능력이 부족한 사람에게 가정법원이 한정된 범위에서 후견인을 두는 제도이다.","r":[]},"후견계약":{"d":"본인이 정신적 제약이 생길 때에 대비해 후견인과 사무 범위를 미리 정하는 계약이다.","r":[]},"미성년후견인":{"d":"친권자가 없는 미성년자의 보호와 재산 관리를 맡는 사람이다.","r":[]},"특별대리인":{"d":"친권자와 자녀 사이에 이해가 충돌할 때 가정법원이 선임해 자녀를 대리하게 하는 사람이다.","r":[]},"부양의무":{"d":"친족 사이에 생활 능력이 없는 사람을 도와야 하는 법적 의무이다.","r":[]},"제사주재자":{"d":"공동상속인 간 협의가 안 될 때 민법 판례에 따라 제사를 이끄는 사람이다.","r":[]},"의사능력":{"d":"자기 행위의 의미와 결과를 합리적으로 판단할 수 있는 정신적 능력이다.","r":[]},"비진의표시":{"d":"표의자가 진의와 다름을 알면서 하는 의사표시로, 원칙적으로 유효하다.","r":[]},"착오":{"d":"표시와 진의가 일치하지 않는데 표의자가 이를 모르는 것으로, 중요 부분이면 취소할 수 있다.","r":[]},"무권대리":{"d":"대리권 없이 타인을 대리해 한 행위로, 본인이 추인하지 않으면 본인에게 효력이 없다.","r":[]},"추인":{"d":"무효나 불확정한 행위를 사후에 확정적으로 인정하는 의사표시이다.","r":[]},"불공정한 법률행위":{"d":"궁박, 경솔, 무경험을 이용해 현저히 균형을 잃은 대가를 얻는 법률행위로 무효이다.","r":[]},"반사회적 법률행위":{"d":"선량한 풍속 그 밖의 사회질서에 위반하여 무효가 되는 법률행위이다.","r":[]},"제한능력자":{"d":"미성년자, 피성년후견인 등 단독으로 완전한 법률행위를 하기 어려운 사람이다.","r":[]},"비법인사단":{"d":"법인격은 없지만 구성원과 독립된 단체로서 실체를 가진 사람들의 모임이다.","r":[]},"종중":{"d":"공동선조의 분묘 수호와 제사, 종원 간 친목을 위한 자연발생적 종족 집단이다.","r":[]},"신의칙":{"d":"권리 행사와 의무 이행은 신의에 따라 성실히 해야 한다는 원칙이다.","r":[]},"권리남용":{"d":"권리를 행사하지만 사회적으로 용인되기 어려운 방법으로 하는 것으로, 허용되지 않는다.","r":[]},"동시이행의 항변권":{"d":"쌍무계약에서 상대방이 이행을 제공할 때까지 자기 채무의 이행을 거절할 수 있는 권리이다.","r":[]},"이행지체":{"d":"이행기가 도래하고 이행이 가능한데도 채무자가 책임 있는 사유로 이행하지 않는 것이다.","r":[]},"수령지체":{"d":"채권자가 이행을 받지 않거나 받을 수 없어 채권자지체가 되는 상태이다.","r":[]},"계약금":{"d":"계약 체결 때 주고받는 금전으로, 이행에 착수하기 전에는 해약금으로 해제할 수 있다.","r":[]},"합의해지":{"d":"계속적 계약에서 당사자가 새로운 합의로 계약의 효력을 장래에 향해 소멸시키는 것이다.","r":[]},"하자담보책임":{"d":"매매 목적물에 하자가 있을 때 매도인이 지는 책임이다.","r":[]},"제3자를 위한 계약":{"d":"계약 당사자가 제3자에게 직접 권리를 취득하게 하기로 하는 계약이다.","r":[]},"수익의 의사표시":{"d":"제3자를 위한 계약에서 제3자가 계약의 이익을 받겠다고 하는 의사표시이다.","r":[]},"지상물매수청구권":{"d":"임대차 종료 때 임차인이 지상 건물을 임대인에게 사 달라고 청구하는 권리이다.","r":[]},"부속물매수청구권":{"d":"임차인이 임대인 동의로 부속한 물건을 임대차 종료 때 임대인에게 사 달라고 청구하는 권리이다.","r":[]},"준소비대차":{"d":"금전 등을 지급할 의무가 있는 경우에 그 목적물을 소비대차의 목적물로 삼기로 약정하는 것이다.","r":[]},"조합":{"d":"둘 이상이 상호 출자하여 공동사업을 경영하기로 약정하는 계약이다.","r":[]},"위임계약":{"d":"당사자 일방이 상대방에게 사무의 처리를 위탁하고 상대방이 승낙하는 계약이다.","r":[]},"도급":{"d":"수급인이 일을 완성하고 도급인이 그 결과에 보수를 지급하기로 하는 계약이다.","r":[]},"지체상금":{"d":"수급인이 공사를 약정한 기한까지 완성하지 못했을 때 지급하기로 한 손해배상액의 예정이다.","r":[]},"위약벌":{"d":"채무불이행 시 제재로 징수하는 금액으로, 손해배상액의 예정과 구분된다.","r":[]},"채권최고액":{"d":"근저당권으로 담보되는 한도액으로, 등기에 기재된다.","r":[]},"공동저당":{"d":"동일한 채권을 담보하기 위해 여러 개의 부동산에 저당권을 설정하는 것이다.","r":[]},"물상대위":{"d":"담보 목적물이 멸실·훼손·수용되어 받게 되는 금전에 담보물권의 효력이 미치는 것이다.","r":[]},"양도담보":{"d":"담보 목적으로 소유권 등을 채권자에게 이전하는 방법이다.","r":[]},"가등기담보":{"d":"금전채무를 담보하기 위해 채권자가 나중에 소유권을 넘겨받을 권리를 가등기로 보전하는 담보이다.","r":[]},"점유개정":{"d":"양도인이 목적물을 계속 점유하면서 양수인을 위해 점유한다는 의사로 점유 이전을 갈음하는 방법이다.","r":[]},"질권":{"d":"채권자가 담보로 받은 물건이나 권리를 점유하며 변제받을 때까지 유치하고 우선변제를 받는 담보물권이다.","r":[]},"임차권등기":{"d":"임대차 종료 후 보증금을 돌려받지 못한 임차인이 단독으로 신청해 하는 등기이다.","r":[]},"확정일자":{"d":"계약서 등에 부여하는 법적 증거 일자로, 채권양도의 제3자 대항요건에 필요하다.","r":[]},"소액임차인":{"d":"보증금이 일정액 이하인 임차인으로, 일정 금액까지 최우선 변제를 받는 사람이다.","r":[]},"자력탈환권":{"d":"점유자가 부동산 점유를 침탈당한 직후 가해자를 배제하고 스스로 점유를 되찾을 수 있는 권리이다.","r":[]},"점유회수의 청구":{"d":"점유를 침탈당한 점유자가 물건의 반환과 손해배상을 청구하는 권리이다.","r":[]},"타주점유":{"d":"소유의 의사 없이 타인의 소유를 인정하며 하는 점유이다.","r":[]},"간접점유":{"d":"임대차 등을 통해 타인으로 하여금 점유하게 하고 그에게 반환을 청구할 수 있는 지위에서 하는 점유이다.","r":[]},"취득시효":{"d":"일정 기간 점유를 계속한 사람이 소유권이나 용익물권 등을 취득하는 제도이다.","r":[]},"물권적 청구권":{"d":"소유권 등이 침해될 때 반환, 방해제거, 방해예방을 청구하는 물권에 기한 권리이다.","r":[]},"원인무효등기":{"d":"실체관계와 맞지 않는 원인으로 마쳐진 등기로, 말소를 청구할 수 있다.","r":[]},"등기의 추정력":{"d":"등기가 있으면 그 내용대로 적법한 권리관계가 있다고 추정하는 효력이다.","r":[]},"중간생략등기":{"d":"소유권이 순차로 이전된 경우 중간자를 건너뛰고 최초 양도인에서 최종 양수인으로 직접 하는 등기이다.","r":[]},"소유권보존등기":{"d":"미등기 부동산에 대해 처음으로 하는 소유권 등기이다.","r":[]},"계약명의신탁":{"d":"명의수탁자가 자기 이름으로 매매계약을 체결하고 등기도 자기 명의로 하는 명의신탁이다.","r":[]},"3자간 등기명의신탁":{"d":"신탁자가 매도인과 계약하고 등기는 수탁자 명의로 직접 이전하는 명의신탁이다.","r":[]},"부동산실명법":{"d":"부동산 소유권을 타인 명의로 등기하는 명의신탁을 금지하는 법이다.","r":[]},"불법원인급여":{"d":"불법한 원인으로 급부를 한 경우 그 반환을 청구할 수 없다는 법리이다.","r":[]},"악의의 수익자":{"d":"자신의 이익 보유가 법률상 원인 없다는 것을 알고 있는 이득자로, 받은 이익에 이자를 붙여 반환한다.","r":[]},"비용상환청구권":{"d":"점유자가 물건에 지출한 필요비나 유익비를 회복자에게 상환받는 권리이다.","r":[]},"공유물분할청구":{"d":"공유자가 공유 관계를 끝내기 위해 공유물의 분할을 청구하는 형성의 소이다.","r":[]},"구분소유권":{"d":"건물의 구조상 독립된 부분을 별개의 소유권 대상으로 소유하는 권리이다.","r":[]},"상린관계":{"d":"인접한 토지 소유자 사이에 서로의 이용을 조절하는 법률관계이다.","r":[]},"지상권":{"d":"타인의 토지에 건물이나 수목 등을 소유하기 위해 그 토지를 사용하는 용익물권이다.","r":[]},"지역권":{"d":"자기 토지의 편익을 위해 타인의 토지를 이용하는 용익물권이다.","r":[]},"전세권":{"d":"전세금을 지급하고 타인의 부동산을 점유해 사용·수익하며 후순위 채권자보다 우선변제받는 물권이다.","r":[]},"피담보채권":{"d":"담보물권이나 보증 등으로 담보되는 채권이다.","r":[]},"가등기담보권":{"d":"금전채권을 담보하기 위해 가등기로 소유권 이전을 보전하는 담보권이다.","r":[]},"시효중단":{"d":"청구, 압류, 승인 등의 사유로 진행된 시효기간이 효력을 잃고 다시 시작하는 것이다.","r":[]},"채무승인":{"d":"채무자가 채권자의 권리가 있음을 안다는 뜻을 표시하는 관념의 통지로, 시효중단 사유이다.","r":[]},"시효이익의 포기":{"d":"시효가 완성된 후 채무자가 시효의 이익을 받지 않겠다는 의사표시이다.","r":[]},"해제조건":{"d":"조건이 성취되면 법률행위의 효력이 소멸하는 조건이다.","r":[]},"일부무효":{"d":"법률행위의 일부가 무효이면 나머지도 무효로 하지만 당사자가 나머지만으로도 행했을 때는 유효하다는 법리이다.","r":[]},"무효행위의 전환":{"d":"무효인 법률행위가 다른 법률행위의 요건을 갖춘 때 당사자 의사에 따라 그 효력을 인정하는 것이다.","r":[]},"유동적 무효":{"d":"토지거래허가를 받기 전처럼 허가를 받으면 소급해 유효하게 될 수 있는 무효 상태이다.","r":[]},"채권자취소권":{"d":"채권자가 채무자의 사해행위를 취소하고 재산을 원상회복시키는 권리이다.","r":[]},"피보전채권":{"d":"채권자취소권이나 채권자대위권 등으로 보전하려는 채권이다.","r":[]},"채권자대위권":{"d":"채권자가 자기 채권을 보전하기 위해 채무자의 권리를 대신 행사하는 권리이다.","r":[]},"전득자":{"d":"수익자로부터 다시 사해행위의 목적물을 취득한 사람이다.","r":[]},"가액배상":{"d":"원물반환이 어려울 때 사해행위 목적물의 가액 상당을 배상하게 하는 것이다.","r":[]},"변제충당":{"d":"채무자가 여러 채무 중 하나를 갚을 때 어느 채무를 소멸시킬지 정하는 것이다.","r":[]},"변제공탁":{"d":"채권자가 수령을 거절하는 등의 경우 변제 목적물을 공탁소에 맡겨 채무를 면하는 제도이다.","r":[]},"대위변제":{"d":"변제할 정당한 이익이 있는 사람이 채무자를 대신 변제하고 채권자의 권리를 취득하는 것이다.","r":[]},"상계":{"d":"서로 같은 종류의 채권을 가진 두 사람이 대등액에서 채권과 채무를 소멸시키는 의사표시이다.","r":[]},"수동채권":{"d":"상계에서 상대방이 가진 채권으로, 상계하는 사람이 부담하는 채무에 해당한다.","r":[]},"상계적상":{"d":"상계가 가능하도록 양 채권이 대립하고 변제기가 도래한 상태이다.","r":[]},"채권양도":{"d":"채권자가 채권을 동일성을 유지한 채 제3자에게 이전하는 계약이다.","r":[]},"양도금지특약":{"d":"당사자가 채권의 양도를 금지하기로 정한 특약이다.","r":[]},"전부명령":{"d":"압류한 금전채권을 채권자에게 이전시켜 채무 변제에 갈음하게 하는 집행법원의 명령이다.","r":[]},"중첩적 채무인수":{"d":"제3자가 채무를 인수하되 종래 채무자도 채무를 계속 부담하는 계약이다.","r":[]},"경개":{"d":"기존 채무를 소멸시키고 새로운 채무를 성립시키는 계약이다.","r":[]},"준점유자":{"d":"채권의 존재를 믿을 만한 외관을 가진 사람으로, 선의·무과실의 변제는 유효하다.","r":[]},"불법행위":{"d":"고의 또는 과실로 위법하게 타인에게 손해를 입혀 손해배상책임이 생기는 행위이다.","r":[]},"공작물 설치·보존의 하자":{"d":"공작물이 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태이다.","r":[]}},"notes":{"2026. 3. 17. 개정 제1008조 단서로, 특별한 부양이나 재산 유지·증가에 대한 보상으로 한 증여·유증은 기여에 상응하는 범위에서 특별수익이 아니며, 이 조문은 유류분에도 준용됨(제1118조)":"2026. 3. 17. 개정 제1008조 단서에 따라 특별한 부양이나 재산 증가의 보상으로 한 증여·유증은 기여 범위에서 특별수익이 아닙니다.","2026. 3. 17. 개정 제1115조 제1항에 따라 유류분권리자는 부족한 한도에서 증여·유증받은 재산의 가액 지급을 청구하고, 청구한 날부터 이자가 붙음":"2026. 3. 17. 개정 제1115조 제1항에 따라 유류분 부족분은 가액으로 청구하고 청구일부터 이자가 붙습니다.","20년간 소유의 의사로 평온·공연하게 점유한 사람은 등기해야 소유권을 취득하고(제245조 제1항), 기간 완성만으로는 등기청구권이 생길 뿐이며 미등기 부동산도 같음":"20년 동안 소유할 의사로 평온·공연하게 점유한 사람은 기간이 차면 등기청구권을 얻고, 등기를 마쳐야 소유권을 얻습니다.","2년 이상 지료를 내지 않으면 소멸을 청구할 수 있는데(제287조), 토지 양도 전후의 연체기간은 합산하지 않고, 법정지상권의 지료가 정해지지 않았으면 지체가 되지 않음":"지료를 2년 이상 안 내면 소멸을 청구하나, 토지 양도 전후 연체는 합산하지 않으며 지료가 안 정해졌으면 지체가 아닙니다.","2인 조합에서 1인이 탈퇴하면 해산·청산 없이 조합재산은 남은 조합원의 단독소유":"2인으로 이뤄진 조합에서 한 명이 탈퇴하면 해산·청산 없이 조합재산이 남은 조합원 단독의 소유가 됩니다.","3자간 등기명의신탁은 약정과 등기는 무효이나 매도인과 신탁자 사이의 매매계약은 유효해서 신탁자는 매도인을 대위해 수탁자 등기의 말소를 구할 수 있음":"3자간 등기명의신탁은 약정과 등기가 무효지만 매매계약은 유효하여, 신탁자가 매도인을 대위해 수탁자 등기의 말소를 구할 수 있습니다.","가등기담보법은 차용물 반환에 관해 다른 재산권 이전을 예약한 경우에 적용되므로 매매대금채권 담보 가등기에는 적용되지 않음":"가등기담보법은 빌린 돈 반환을 위해 재산권 이전을 예약한 때 적용되므로 매매대금채권 담보 가등기에는 해당하지 않습니다.","가등기에 기한 본등기를 하면 순위만 가등기 때로 소급하고 물권변동의 효력은 소급하지 않음":"가등기에 기한 본등기는 순위만 가등기 시점으로 올려 줄 뿐 물권변동 시점까지 올리지는 않습니다.","가정법원의 결정에는 법령 위반을 이유로만 비송사건절차법에 따라 항고 가능(가족관계등록법 제112조)":"가정법원의 결정에 대해서는 법령 위반을 이유로 할 때만 비송사건절차법에 따라 항고할 수 있습니다.","가정폭력피해자는 배우자나 직계혈족을 교부제한대상자로 지정해 자기 증명서의 교부를 제한해 달라고 신청할 수 있고, 지정된 사람은 부모·자녀라도 인터넷으로도 피해자의 증명서를 받거나 열람할 수 없음":"가정폭력피해자가 배우자나 직계혈족을 교부제한대상자로 지정하면 부모·자녀라도 인터넷으로도 피해자의 증명서를 받거나 열람할 수 없습니다.","가족관계·기본·혼인관계·입양관계·친양자입양관계증명서가 있고 각각 일반증명서와 상세증명서로 발급(법 제15조)":"증명서로는 가족관계, 기본, 혼인관계, 입양관계, 친양자입양관계 증명서가 있고 각각 일반과 상세로 발급합니다.","가족관계증명서의 특정증명서에는 부모·배우자·자녀 중 신청인이 선택한 사람이 나오고 여러 명을 고를 수 있으며 혼인관계증명서의 특정증명서에는 신청인이 고른 과거 배우자 한 사람과의 혼인만 나오고 현재 혼인은 나오지 않음":"가족관계증명서 특정증명서에는 신청인이 고른 부모·배우자·자녀가, 혼인관계증명서 특정증명서에는 고른 과거 배우자 한 사람과의 혼인만 나옵니다.","가족관계증명서 일반증명서에는 배우자와 생존한 현재의 혼인 중 자녀만 나오고, 혼인관계증명서 일반증명서에는 현재의 혼인만 나오며, 기본증명서 일반증명서에는 출생·사망·국적상실이 나옴":"일반증명서에는 가족관계증명서는 배우자와 혼인 중 자녀, 혼인관계증명서는 현재 혼인, 기본증명서는 출생·사망·국적상실이 나옵니다.","감독법원의 신고서류편철부 보존기간은 30년이고 그 연도의 다음 해부터 기산(규칙 제83조, 제84조)":"감독법원이 보관하는 신고서류편철부의 보존기간은 30년이며, 그 연도의 다음 해부터 기산합니다.","감독법원의 허가를 받아 직권 정정(가족관계등록법 제18조 제2항)":"이런 경우에는 감독법원의 허가를 받아 직권으로 정정할 수 있습니다.","강박에 의한 취소를 소장으로 하면 소장 부본이 제척기간 안에 도달해야 함":"강박을 이유로 소장으로 취소하려면 소장 부본이 제척기간 안에 상대방에게 도달해야 합니다.","강제집행을 면하려는 허위 근저당권설정은 반사회질서 위반이 아님(제103조)":"강제집행을 피하려는 허위 근저당권설정은 제103조가 말하는 반사회질서 위반에 해당하지 않습니다.","같은 사람 소유의 토지와 건물이 매매·증여·강제경매·공매 등으로 소유자가 달라지고 철거 특약이 없으면 건물소유자가 관습법상 법정지상권을 취득하며 미등기·무허가 건물도 같음":"토지와 건물이 한 사람 것이었다가 매매·경매 등으로 소유자가 달라지고 철거 특약이 없으면 건물소유자가 관습법상 법정지상권을 갖습니다.","같은 사람이 성명이나 출생연월일을 달리해 등록부가 둘 이상 있음이 명백하면 감독법원의 허가를 받아 직권으로 정리(규칙 제59조)":"같은 사람의 등록부가 성명이나 출생연월일만 다르게 둘 이상 있음이 분명하면 감독법원 허가를 받아 직권으로 정리합니다.","개명신고는 가정법원 허가서 등본을 받은 날부터 1개월 안에 함(가족관계등록법 제97조, 제99조)":"개명신고는 가정법원 허가서 등본을 받은 날부터 1개월 안에 해야 합니다.","개명하려는 사람은 주소지(재외국민은 등록기준지) 관할 가정법원의 허가를 받음":"개명하려는 사람은 주소지를 관할하는 가정법원의 허가를 받아야 하고, 재외국민은 등록기준지 관할 법원입니다.","거주국 방식으로 혼인·입양·인지·이혼 등이 성립한 경우":"혼인·입양·인지·이혼 등이 현지 방식에 따라 성립한 경우를 말합니다.","건물 소유 목적의 토지임대차가 기간 만료로 끝나 갱신이 거절되면 임차인은 지상건물의 매수 청구 가능(제643조)":"건물 소유가 목적인 토지임대차가 기간 만료로 끝나고 갱신이 거절되면 임차인은 지상건물의 매수를 청구할 수 있습니다.","건물소유자 아닌 점유자에게는 대항력 있는 임차인이라도 퇴거를 청구 가능":"건물을 소유하지 않은 점유자는 대항력 있는 임차인이라도 토지소유자의 퇴거 청구를 받을 수 있습니다.","건물에 근저당권이 있거나 무허가 건물이어도 대상":"건물에 근저당권이 설정되어 있거나 무허가 건물이어도 매수청구의 대상이 됩니다.","건물을 경매로 취득한 매수인은 특별한 사정이 없으면 등기 없이 법정지상권도 취득":"건물을 경매로 산 매수인은 특별한 사정이 없으면 법정지상권도 등기 없이 취득합니다.","건물을 신축한 사람은 등기 없이 원시취득":"건물을 새로 지은 사람은 등기하지 않아도 소유권을 처음으로 취득합니다.","건물 일부의 전세권자는 건물 전부에서 우선변제를 받지만 나머지 부분에 대해서는 경매를 청구하지 못하고, 소멸 시 목적물 인도·말소서류 교부와 전세금 반환은 동시이행(제317조)":"건물 일부 전세권자도 건물 전부에서 우선변제를 받되 나머지 부분의 경매는 못 구하며, 소멸 후 인도·서류 교부와 반환은 동시이행입니다.","견고한 건물이나 수목 소유를 목적으로 기간을 정하면 30년보다 짧게 정하지 못하고(제280조 제1항), 존속기간을 영구로 약정하는 것도 허용":"견고한 건물이나 수목 소유를 위한 지상권은 기간을 30년보다 짧게 못 정하고, 영구 존속으로 약정하는 것도 허용됩니다.","경과 여부는 법원이 직권 조사":"제척기간이 지났는지는 당사자가 말하지 않아도 법원이 직권으로 조사합니다.","경매개시결정 기입등기로 압류 효력이 생기기 전에 유치권을 취득했으면 근저당권 설정 뒤라도 경매 매수인에게 대항할 수 있음":"압류 효력이 생기기 전에 취득한 유치권은 근저당권이 앞서 설정되었더라도 경매 매수인에게 맞설 수 있습니다.","경매의 기초가 된 등기가 원인무효여서 경매 자체가 무효라면 담보책임 없음(제578조)":"경매의 기초가 된 등기가 원인무효여서 경매 자체가 무효라면 담보책임이 생기지 않습니다.","계약관계 등 적법한 권원으로 지출했다면 그 계약 상대방에게만 청구 가능":"계약관계 같은 적법한 권원에 따라 비용을 썼다면 그 계약 상대방에게만 청구할 수 있습니다.","계약금을 교부했으면 당사자 일방이 이행에 착수할 때까지":"계약금을 주고받았다면 당사자 한쪽이 이행에 착수하기 전까지 해약금 규정에 따라 계약을 풀 수 있습니다.","계약금을 약정만 하고 교부하지 않았으면 해약금 해제 불가":"계약금을 약정만 하고 실제로 주지 않았다면 해약금에 의한 해제는 할 수 없습니다.","계약명의신탁에서 매도인이 선의면 수탁자가 소유권을 취득하고 신탁자는 매수자금 상당의 부당이득반환을 청구하며 매도인이 악의면 소유권은 매도인에게 남음":"계약명의신탁에서 매도인이 선의면 수탁자가 소유권을 갖고 악의면 매도인에게 남으며, 신탁자는 선의일 때 매수자금 상당액을 부당이득으로 청구합니다.","계약상 채권의 양수인이나 그 채권으로 가처분을 한 사람은 해당하지 않음":"계약상 채권을 사들인 사람이나 그 채권으로 가처분한 사람은 이 보호 대상인 제삼자에 속하지 않습니다.","계약 유지가 중대한 불균형을 초래하면 해제·해지 가능":"이런 변화로 계약을 유지하면 심한 불균형이 생길 때 계약을 해제하거나 해지할 수 있습니다.","계약의 기초가 된 사정이 현저히 바뀌고 예견할 수 없었던 경우":"계약의 바탕이 된 사정이 크게 바뀌고 당사자가 미리 알 수 없었던 경우를 가리킵니다.","계약 일방이 상대방의 지시로 제3자에게 직접 급부한 삼각관계에서는 원인관계에 흠이 있고 제3자가 이를 알았더라도 제3자가 아니라 계약 상대방에게 반환을 구해야 함":"지시에 따라 제3자에게 직접 급부한 삼각관계에서는 원인관계에 흠이 있어도 제3자가 아니라 계약 상대방에게 반환을 구해야 합니다.","계약 체결 후 상대방의 해제 의사표시를 수령할 권한은 없음":"계약을 맺은 뒤 상대방이 하는 해제 의사표시를 대신 받을 권한까지는 대리인에게 없습니다.","고의의 불법행위로 인한 채무자는 상계로 대항하지 못하지만(제496조) 피해자가 그 채권을 자동채권으로 상계하는 것은 되고, 수탁보증인의 사전구상권을 자동채권으로 한 상계는 허용되지 않음":"고의 불법행위 채무자는 상계로 맞설 수 없으나 피해자 쪽 상계는 되고, 수탁보증인이 가진 사전구상권을 자동채권으로 쓸 수는 없습니다.","고의·중과실이 아니고 배상으로 생계에 중대한 영향이 있으면 배상의무자는 경감을 청구할 수 있음(제765조)":"고의나 중과실이 아니고 배상이 생계에 중대한 영향을 준다면 배상의무자는 배상액 경감을 청구할 수 있습니다.","공동불법행위에서 피해자의 과실은 가해자 각자가 아니라 전원에 대한 과실로 전체적으로 평가":"공동불법행위에서 피해자 과실은 가해자별이 아니라 전원에 대한 과실로 한꺼번에 평가합니다.","공동불법행위자는 부진정연대책임을 지므로 1인에 대한 이행청구는 다른 사람에게 시효중단 효력이 없고, 자기 부담부분을 넘어 배상한 사람은 다른 공동불법행위자에게 구상할 수 있으며 상대방의 채무가 이미 시효로 소멸했어도 마찬가지":"공동불법행위자는 부진정연대책임이라 한 명에 대한 청구로는 다른 사람의 시효가 중단되지 않고, 더 낸 사람은 나머지에게 구상합니다.","공동상속인 1인이 다른 상속인의 동의 없는 무효의 협의분할로 이전등기를 했다면 그 말소청구는 상속회복청구에 해당하고, 포괄적 수유자도 상속회복청구를 할 수 있음":"공동상속인 한 명이 무효의 협의분할로 이전등기를 한 경우 말소청구는 상속회복청구이며, 포괄적 수유자도 청구할 수 있습니다.","공동선조와 성과 본이 같은 후손은 성별 구별 없이 성년이 되면 당연히 종중원":"공동선조의 후손으로 성과 본이 같으면 성별과 관계없이 성년이 되는 순간 종중원이 됩니다.","공사대금채권과 수급인의 저당권설정청구권은 3년":"공사대금채권과 수급인의 저당권설정청구권은 3년의 단기시효에 걸립니다.","공유물분할 소송에서 현물분할 조정이 성립해도 분할에 따른 등기를 마친 때 물권변동":"현물분할 조정이 성립했더라도 분할 등기까지 마쳐야 물권이 실제로 바뀝니다.","공유자 1인이 다른 공유자 동의 없이 특정 부분을 팔아 이전등기를 했다면 그 등기는 처분한 공유자의 지분 범위에서는 유효":"공유자 한 명이 특정 부분을 팔고 이전등기를 했다면 그 등기는 그 공유자의 지분 범위 안에서는 유효합니다.","공유자가 지분을 포기하면 다른 공유자에게 지분 비율로 귀속하지만(제267조), 포기는 상대방 있는 단독행위여서 다른 공유자 앞으로 등기를 해야 물권변동이 생김":"공유지분의 포기는 상대방 있는 단독행위여서 다른 공유자에게 등기를 해야 물권변동의 효력이 생깁니다.","공유자는 언제든 분할을 청구할 수 있으나 5년 내의 기간으로 분할하지 않기로 약정할 수 있음(제268조 제1항)":"공유자는 언제든 분할을 청구할 수 있고, 다만 5년 이내의 기간 동안 분할하지 않기로 약정할 수 있습니다.","공작물의 설치·보존상 하자로 생긴 손해는 1차로 점유자가 배상하고, 점유자가 필요한 주의를 다했음을 증명해 면책되면 소유자가 배상(제758조 제1항)":"공작물 하자로 생긴 손해는 먼저 점유자가 배상하고, 점유자가 주의의무를 다했음을 증명하면 소유자가 배상합니다.","과거 양육비 상환청구권의 소멸시효는 자녀가 미성년인 동안 진행하지 않고 성년이 된 때부터 진행":"과거 양육비를 돌려받을 권리의 시효는 자녀가 미성년이면 멈춰 있다가 성년이 되면서 흐르기 시작합니다.","과실로 피상속인을 사망에 이르게 한 사람은 결격자가 아님":"과실로 피상속인이 사망하게 한 사람은 상속결격자에 해당하지 않습니다.","관리에 관한 사항은 지분의 과반수로 정하므로, 과반수 지분권자는 협의 없이도 특정 부분을 배타적으로 사용·수익하기로 정할 수 있음":"관리 사항은 지분 과반수로 정하므로, 과반수 지분권자는 다른 공유자와 협의하지 않아도 특정 부분을 독점 사용하도록 정할 수 있습니다.","관습법상 법정지상권은 등기 없이 취득하고 그 뒤 토지를 산 제3자에게도 등기 없이 주장할 수 있음":"관습법상 법정지상권은 등기 없이 얻고, 뒤에 토지를 산 제3자에게도 등기 없이 내세울 수 있습니다.","교부자는 포기, 수령자는 배액 상환으로 해제 가능(제565조)":"계약금을 준 쪽은 포기하고, 받은 쪽은 배액을 돌려주는 방식으로 계약을 해제할 수 있습니다.","구를 둔 시에서는 구청장이, 도농복합형태의 시에서는 동지역은 시장, 읍·면지역은 읍·면장이 처리":"구가 있는 시는 구청장이, 도농복합형태의 시는 동지역은 시장이 읍·면지역은 읍·면장이 등록사무를 맡습니다.","구상의무자가 여럿이면 원칙적으로 분할채무이지만 구상권자에게 과실이 없으면 부진정연대채무가 됨":"구상의무자가 여럿이면 분할채무가 원칙이지만, 구상권자에게 잘못이 없으면 부진정연대채무가 됩니다.","국내에 살지 않으면 서울가정법원이 확인(가족관계등록법 제75조 제1항)":"국내에 살지 않는 부부는 서울가정법원에서 확인을 받습니다.","국적상실 신고는 배우자나 4촌 이내 친족이 안 날부터 1개월 안에 함":"국적상실 신고는 사실을 안 배우자나 4촌 이내 친족이 알게 된 날부터 1개월 안에 합니다.","궁박·경솔·무경험으로 현저하게 공정을 잃은 법률행위는 무효(제104조)":"궁박·경솔·무경험 때문에 현저히 공정하지 못하게 이뤄진 법률행위는 무효입니다.","권리 일부가 타인에게 속한 경우 손해액은 이전할 수 없게 된 때의 그 부분 시가":"권리 일부가 타인 것인 경우 손해액은 이전할 수 없게 된 때 그 부분의 시가로 셈합니다.","권리 전부가 타인에게 속해 이전할 수 없으면 매수인은 매도인의 귀책사유를 묻지 않고 해제 가능":"권리 전부가 타인 것이어서 이전할 수 없으면 매수인은 매도인의 귀책 여부와 관계없이 계약을 해제할 수 있습니다.","권원 없이 점유한 악의 수익자는 사용이익에 이자를 붙여 반환하고 그 이자의 지연손해금도 냄":"권원 없이 점유한 악의 수익자는 이용 이익에 이자를 더하고, 그 이자에 대한 지연손해금까지 물어야 합니다.","권원이 분명하지 않으면 자주점유로 추정되고 국가·지방자치단체의 점유에도 추정이 미치지만 취득 원인이 없음을 알면서 무단점유한 사실이 증명되면 추정이 깨짐":"권원이 불분명하면 자주점유로 추정되지만, 취득 원인이 없음을 알면서 무단으로 점유한 사실이 증명되면 추정이 깨집니다.","그것만으로 본등기청구권이 혼동으로 소멸하지 않음":"그런 경우라도 본등기청구권은 혼동으로 소멸하지 않고 남아 있습니다.","그 뒤 출생신고 때 바꿀 수 없음":"혼인신고 이후 출생신고 때에는 그 협의를 뒤늦게 바꿀 수 없습니다.","그 물권이 제3자 권리의 목적이거나 본인·제3자를 위해 존속시킬 필요가 있으면 소멸하지 않음(제191조)":"혼동으로 없어지는 물권이 제3자의 권리 대상이거나 존속시킬 이익이 있으면 소멸하지 않습니다.","그에 따라 등록부도 폐쇄 없이 해당 사항만 정정(가족관계등록규칙 제66조의2 제2항)":"제적부를 정정하는 데 따라 등록부도 폐쇄하지 않고 해당 사항만 고칩니다.","그 이행불능을 이유로 손해배상을 청구하지도 못함":"말소청구가 이행불능이 되었다 하더라도 그것을 이유로 한 손해배상은 청구할 수 없습니다.","그 잘못이 시·읍·면의 장에게 있으면 통지하지 않음(가족관계등록법 제18조 제1항)":"그 잘못이 시·읍·면의 장에게 있는 경우에는 통지하지 않습니다.","그 허락을 받은 점유자에게 소수지분권자는 철거나 퇴거를 구하지 못함":"과반수 지분권자의 허락을 받은 점유자에게 소수지분권자가 철거나 퇴거를 요구할 수는 없습니다.","근저당권이 설정된 부동산 매매에서 매도인의 말소·이전등기의무와 매수인의 잔대금지급의무는 동시이행":"근저당이 걸린 부동산을 팔 때 말소와 이전등기를 해 줄 의무와 잔대금을 낼 의무는 맞교환 관계입니다.","근저당권자가 경매를 신청하면 그때 피담보채권이 확정되고 신청을 취하해도 번복되지 않음":"근저당권자가 경매를 신청하는 순간 피담보채권이 확정되며, 신청을 취하해도 되돌리지 못합니다.","근친혼 같은 장애사유는 양쪽에 누적 적용":"근친혼 같은 장애사유는 양쪽 본국법을 모두 누적해서 적용합니다.","금전채권 같은 가분채권은 원칙적으로 분할 대상이 아니나 형평을 위해 예외적으로 대상이 될 수 있고, 가분채무를 1인이 법정상속분을 넘어 부담하기로 한 협의는 면책적 채무인수의 실질을 가짐":"금전채권 같은 가분채권은 원칙적 분할 대상이 아니나 형평상 예외가 있고, 가분채무를 더 맡는 협의는 면책적 채무인수의 실질입니다.","금전채권 질권자가 직접청구해 받았는데 입질채권이 존재하지 않았다면 제3채무자는 질권설정자에게만 부당이득반환을 구함":"입질채권이 없었는데 질권자가 직접 받아 갔다면 제3채무자는 질권설정자에게만 부당이득 반환을 구할 수 있습니다.","금전채무 불이행에서 채권자는 손해를 증명할 필요가 없고 채무자는 과실 없음을 항변하지 못하며(제397조 제2항), 약정이율이 법정이율보다 낮으면 법정이율에 따름":"금전채무를 이행하지 않으면 채권자는 손해를 증명할 필요가 없고, 약정이율이 법정이율보다 낮으면 법정이율을 따릅니다.","급박한 위해를 피하려는 긴급사무관리는 고의나 중대한 과실이 없으면 배상책임이 없고(제735조), 과실 없이 입은 손해는 본인의 현존이익 한도에서 보상받음(제740조)":"긴급사무관리는 고의나 중과실이 없으면 배상책임이 없고, 과실 없이 입은 손해는 본인의 현존이익 한도에서 보상받습니다.","기간 만료 뒤 전세권 이전의 부기등기를 했어도 확정일자 있는 증서에 의한 채권양도 절차를 거치지 않으면 압류·전부채권자에게 대항하지 못함":"전세권 이전 부기등기만으로는 부족하고 확정일자 있는 채권양도 절차를 거쳐야 압류·전부채권자에게 맞섭니다.","기간은 사건 발생일부터 셈(가족관계등록법 제37조 제1항)":"신고 기간은 사건이 발생한 날부터 셉니다.","기간을 미리 정하지 않았어도 최고 후 상당한 기간이 지나면 해제권 발생":"이행 기간을 미리 정해 두지 않았더라도 최고한 뒤 상당한 기간이 흐르면 해제권이 생깁니다.","기간이 지나면 참칭상속인이 상속개시 때로 소급해 상속인 지위를 취득하고, 상속재산 일부만 제소했다면 나머지에 대해서는 기간을 지킨 것이 아님":"기간이 지나면 참칭상속인이 상속개시 시점부터 상속인이 되며, 상속재산 일부만 제소한 때 나머지는 기간을 지킨 것이 아닙니다.","기록을 마친 신고서류는 1개월마다 다음 달 10일까지 편철해 감독법원에 보내고, 감독법원은 등록부와 대조·조사해 위법·부당하면 시정지시 등을 명함":"처리를 마친 신고서류는 달마다 다음 달 10일까지 철해 감독법원에 보내고, 감독법원은 대조·조사로 위법·부당하면 시정지시를 합니다.","기록이 법률상 허가될 수 없거나 착오·누락이 있으면 이해관계인이 정정 신청":"기록이 법률상 허용되지 않거나 착오·누락이 있다면 이해관계인이 법원에 정정을 신청합니다.","기여분은 상속개시 때 재산가액에서 유증가액을 뺀 액을 넘지 못함(제1008조의2 제3항)":"기여분은 상속개시 때 재산가액에서 유증가액을 뺀 금액을 넘을 수 없습니다.","기여분이 협의나 심판으로 정해지지 않았으면 유류분반환소송에서 주장할 수 없고, 정해졌더라도 유류분 산정에서 공제하지 않음":"기여분은 협의나 심판으로 정해지기 전에는 유류분반환소송에서 내세울 수 없고, 정해진 뒤에도 유류분 산정에서 빼지 않습니다.","기초재산은 상속개시 때 재산에 증여재산을 더하고 채무 전액을 뺀 것이며(제1113조 제1항), 제3자 증여는 상속개시 전 1년 안의 것만 산입하지만 쌍방이 손해를 알고 한 것은 그 전 것도 산입하고(제1114조), 공동상속인이 받은 특별수익 증여는 기간과 관계없이 산입":"기초재산은 상속개시 때 재산에 증여를 더하고 채무를 뺀 값이며, 제3자 증여는 1년 내 것만, 특별수익은 기간과 무관하게 넣습니다.","기한 없는 채무는 이행청구를 받은 때부터 지체책임을 지고(제387조 제2항), 부당이득반환채무와 확정된 지연손해금채무, 유류분반환의무도 같음":"기한이 없으면 이행 청구를 받은 때부터 지체되며, 부당이득반환채무와 확정 지연손해금채무, 유류분반환의무도 마찬가지입니다.","다른 사람에게 팔린 사실을 아는 것만으로는 부족":"이미 다른 사람에게 팔렸다는 사실을 알고 있었다는 것만으로는 무효 사유가 되기에 부족합니다.","다만 제3자가 그 토지에 건물을 신축하면 방해배제로 신축 건물의 철거와 대지 인도를 구할 수 있음":"그 토지에 제3자가 건물을 지으면 철거와 대지 인도를 방해배제로 요구할 수 있습니다.","다만 피해자가 사무집행이 아님을 알았거나 중대한 과실로 몰랐으면 사용자책임을 물을 수 없음":"피해자가 직무와 무관한 행위임을 알았거나 중과실로 몰랐다면 사용자책임을 묻지 못합니다.","단독입양한 양부가 친생모와 혼인 중이면 양부와 친생모를 부모로 기록하고, 외국인은 성명·성별·출생연월일·국적·외국인등록번호를 기재":"양부가 친생모와 혼인 중인 단독입양은 두 사람을 부모로 적고, 외국인은 성명·성별·출생연월일·국적·외국인등록번호를 적습니다.","담보권 실행 경매의 배당금은 합의가 있어도 법정충당으로 충당":"담보권 실행 경매 배당금은 당사자 합의와 무관하게 법정충당 방식으로 갚은 것으로 칩니다.","담보지상권자는 토지를 무단점유한 사람에게 지상권 침해를 이유로 임료 상당 손해배상을 구할 수 없음":"담보지상권자는 무단 점유자에게 임료 상당 손해를 배상하라고 지상권 침해로 구하지 못합니다.","당사자가 소급 의사를 표시한 때에만 소급(제147조)":"당사자가 소급하기로 의사를 표시한 경우에만 조건 성취의 효력이 소급합니다.","당사자가 여럿이면 해제는 전원이 또는 전원에게 해야 함(제547조 제1항)":"당사자가 여러 명이면 해제의 의사표시는 전원이 하거나 전원에게 해야 합니다.","당사자는 미리 유치권 배제 특약을 할 수 있고 그 효력은 특약 상대방 아닌 사람도 주장할 수 있으며 유치권을 행사해도 피담보채권의 소멸시효는 진행":"유치권은 미리 배제하기로 특약할 수 있고 특약 상대방 아닌 사람도 이를 주장할 수 있으며, 유치권을 행사해도 피담보채권의 시효는 계속 흐릅니다.","대가관계 없는 증여에는 적용 없음(제104조)":"대가가 오가지 않는 증여에는 불공정 법률행위 규정이 적용되지 않습니다.","대가변상 특례도 양수인이 선의·무과실이어야 적용(제251조)":"대가변상 특례도 양수인이 선의이고 무과실일 때에만 적용됩니다.","대리인이 제한능력자일 때도 책임 없음":"무권대리인이 제한능력자라면 상대방에 대한 이행이나 배상 책임이 생기지 않습니다.","대리인이 한 행위는 경솔·무경험을 대리인 기준으로, 궁박을 본인 기준으로 판단":"대리행위의 불공정 여부에서 경솔·무경험은 대리인을, 궁박은 본인을 살핍니다.","대법원장은 재외국민의 등록사무를 가족관계등록관이 처리하게 할 수 있고, 이를 위해 법원행정처에 재외국민 가족관계등록사무소를 둠(법 제4조의2)":"재외국민 등록사무는 가족관계등록관이 처리하도록 정해 두었으며, 법원행정처에 재외국민 가족관계등록사무소가 따로 있습니다.","대위로 이전하는 것은 채권과 담보이고 계약당사자 지위는 이전하지 않으며 확정 전 근저당권의 피담보채권 일부를 대위변제해도 근저당권은 이전하지 않음":"대위로 넘어가는 것은 채권과 담보이지 계약상 지위가 아니며, 확정 전에는 근저당권 피담보채권 일부를 대위변제해도 근저당권이 따라가지 않습니다.","대지와 미등기 건물을 함께 사고 대지만 이전등기한 경우, 토지공유자 1인이 건물을 소유하다 토지 지분만 판 경우에는 성립하지 않음":"대지와 미등기 건물을 함께 사서 대지만 등기했거나, 토지공유자 한 명이 지분만 판 경우는 성립하지 않습니다.","대표권 없는 이사의 행위로는 법인의 불법행위가 성립하지 않음":"대표자가 아닌 이사가 저지른 일은 법인이 불법행위 책임을 질 일이 아닙니다.","대표권 제한은 정관에 기재하지 않으면 효력 없음(제41조)":"대표권 제한은 정관에 적혀 있지 않으면 효력이 없다고 제41조가 정합니다.","대항요건을 갖추지 못한 양수인이 채무자를 상대로 한 재판상 청구도 시효중단 사유가 됨":"대항요건이 없는 양수인이 채무자에게 낸 재판상 청구도 시효를 중단시킵니다.","대항요건을 갖춘 임차권 뒤에 저당권이 설정되었다면 임차인이 소유권을 취득해도 임차권은 소멸하지 않음":"대항요건을 갖춘 임차권이 저당권보다 앞서면 임차인이 소유권을 취득해도 임차권이 혼동으로 사라지지 않습니다.","도급인 명의로 보존등기하기로 합의했다면 건물은 도급인에게 원시적으로 귀속":"도급인 명의로 보존등기하기로 합의했다면 건물의 소유권은 처음부터 도급인에게 돌아갑니다.","도급인의 지체상금채권과 수급인의 공사대금채권도 동시이행관계가 아님":"도급인이 받을 지체상금과 수급인이 받을 공사대금은 서로 동시이행으로 묶이지 않습니다.","동기를 상대방에게 표시해 법률행위의 내용이 되면 충분하고 별도의 합의는 필요 없음":"동기의 착오라도 동기를 상대방에게 알려 계약 내용이 되었다면 충분하며, 따로 합의할 필요는 없습니다.","동시이행관계에 있으면 항변권을 행사하지 않아도 이행지체 책임 없음":"동시이행 관계에 있다면 항변권을 행사하지 않았어도 이행지체 책임이 생기지 않습니다.","등기는 물권의 효력발생요건이고 존속요건이 아님":"등기는 물권의 효력이 생기기 위한 요건이지 효력이 이어지기 위한 요건은 아닙니다.","등기부에 적힌 원인과 다른 원인으로 적법하게 취득했다고 주장해도 추정력은 깨지지 않음":"등기부상 원인과 다른 원인을 내세워도 추정력을 뒤집지는 못합니다.","등기 없이 변동하는 판결은 형성판결만 뜻함(제187조)":"등기 없이 물권이 바뀌는 판결은 형성판결만 가리킵니다.","등기하지 않으면 제3자의 선의·악의를 묻지 않고 대항 불가(제60조)":"대표권 제한을 등기하지 않으면 제3자가 선의인지 악의인지와 관계없이 대항하지 못합니다.","등록된 자동차에는 원칙적으로 선의취득 적용 없음":"등록된 자동차에는 원칙적으로 동산 선의취득이 적용되지 않습니다.","등록부의 기록이 법률상 무효이거나 착오·누락이 있음을 알면 시·읍·면의 장은 신고인이나 본인에게 통지":"등록부 기록에 무효나 착오·누락이 있음을 알게 된 시·읍·면의 장은 신고인이나 본인에게 그 사실을 알려야 합니다.","등록부 정정허가결정만으로 제적부를 정정할 수는 없음":"등록부정정허가결정을 받았더라도 그것만으로 제적부까지 정정할 수는 없습니다.","등록비송에는 검사의 청구인적격 규정이 없음":"등록 관련 비송사건에서는 검사에게 청구인적격을 준 규정이 없습니다.","등록사무는 대법원이 관장하고(법 제2조), 대법원장은 처리 권한을 시·읍·면의 장에게, 감독 권한을 사무소 소재지 관할 가정법원장에게 위임하며 가정법원지원장은 가정법원장의 명을 받아 감독(법 제3조)":"등록사무는 대법원이 관장하고 처리 권한은 시·읍·면의 장에게, 감독 권한은 관할 가정법원장에게 위임되며 가정법원지원장은 명을 받아 감독합니다.","등록창설은 무등록자 본인이 등록하려는 곳 관할 가정법원의 허가를 받아 신청(가족관계등록법 제101조 제1항)":"등록창설은 무등록자 본인이 등록하려는 곳 관할 가정법원의 허가를 받아 신청합니다.","매도인은 인도나 부당이득을 청구하지 못함":"그러므로 매도인은 토지의 인도나 부당이득 반환을 청구할 수 없습니다.","매도인의 하자담보책임이 성립하는지와 상관없이 매수인은 착오로 매매계약 취소 가능":"매도인이 하자담보책임을 지는지와 별개로 매수인은 착오를 이유로 매매계약을 취소할 수 있습니다.","매도인이 계약을 적법하게 해제한 뒤에도 매수인은 착오로 취소 가능":"매도인이 적법하게 계약을 해제한 이후에도 매수인은 착오를 이유로 계약을 취소할 수 있습니다.","매도인이 이행을 최고하고 잔대금 지급 소송을 낸 것만으로는 이행에 착수한 것이 아님":"매도인이 이행을 최고하고 잔대금 지급 소송을 제기했다는 것만으로는 이행에 착수했다고 볼 수 없습니다.","매매계약 체결의 대리인은 중도금·잔금을 수령할 권한과 대금지급기일을 연기해 줄 권한 있음":"매매계약을 체결할 대리인은 중도금과 잔금을 받고 대금 지급기일을 미뤄 줄 권한도 가집니다.","매매로 인한 소유권이전등기청구권의 양도는 채무자의 동의나 승낙이 있어야 대항할 수 있지만 취득시효로 인한 이전등기청구권에는 이 제한이 없음":"매매에 기한 이전등기청구권은 채무자 동의나 승낙이 있어야 대항할 수 있지만 취득시효에 기한 것은 그렇지 않습니다.","매수가격은 청구 당시 시가이며 근저당 피담보채무액을 빼지 않음":"지상물 매수가격은 청구 당시의 시가로 하고 근저당 피담보채무액은 빼지 않습니다.","매수인의 하자담보 손해배상청구권은 목적물을 인도받은 때부터 진행":"매수인의 하자담보 손해배상청구권은 목적물을 넘겨받은 때부터 시효가 흐르기 시작합니다.","면책적인지 중첩적인지 분명하지 않으면 중첩적 인수로 보고, 중첩적 인수인은 채무자의 부탁이 있으면 연대채무, 없으면 부진정연대채무를 짐":"면책적인지 중첩적인지 불분명하면 중첩적 인수이고, 채무자 부탁이 있었다면 연대채무, 없었다면 부진정연대채무가 됩니다.","명예훼손은 사실을 적시해 사회적 평가를 침해하는 것이고, 순수한 의견표명만으로는 성립하지 않음":"명예훼손은 사실을 드러내 사회적 평가를 떨어뜨리는 것이고, 순수한 의견표명만으로는 성립하지 않습니다.","명의신탁자인 가등기권자가 가등기와 관계없이 소유권이전등기를 받아도":"명의신탁자인 가등기권자가 가등기와 무관하게 소유권이전등기를 받은 경우를 가리킵니다.","모를 특정할 수 없거나 모가 소재불명·비협조인 경우":"모를 특정할 수 없거나 모가 소재불명이거나 비협조적인 경우를 말합니다.","모의 성과 본을 따르기로 하는 협의는 혼인신고 때 해야 함":"모의 성과 본을 따르겠다는 협의는 혼인신고를 할 때 해 두어야 합니다.","목적범위 밖 행위로 손해를 입히면 그 의결에 찬성하거나 집행한 사원·이사 등이 연대하여 배상":"법인이 목적 범위 밖에서 손해를 끼치면 의결에 찬성하거나 집행한 사원·이사 등이 함께 배상합니다.","무과실은 요건이 아님, 가장채권을 가압류한 사람과 파산관재인도 제3자":"제3자는 무과실일 필요가 없고, 가장채권을 가압류한 사람이나 파산관재인도 제3자에 속합니다.","무권대리인의 책임은 무과실책임(제135조)":"무권대리인의 책임은 고의나 과실이 없어도 지는 무과실책임입니다.","무권리자가 남의 부동산을 처분해 받은 대금을 반환할 때 자신의 양도소득세 등은 공제하지 못함":"남의 부동산을 판 무권리자가 대금을 돌려줄 때 자기가 낸 양도소득세 등을 빼 달라고 할 수 없습니다.","무인증명서발급기는 본인에게만 발급(법 제14조의3 제2항)":"무인증명서발급기는 본인에게만 증명서를 발급합니다.","무효등기에 터 잡은 가압류채권자가 있으면 진정한 소유자는 말소와 함께 그 채권자의 승낙을 구해야 함(부동산등기법 제57조)":"무효등기를 근거로 가압류한 채권자가 있으면 진정한 소유자는 말소 소송 때 그 채권자의 승낙도 구해야 합니다.","무효 부분이 없더라도 법률행위를 했으리라 인정되면 나머지 유효(제137조)":"무효 부분이 없었더라도 그 법률행위를 했을 것이라 인정되면 나머지 부분은 유효합니다.","무효인 법률행위는 추인해도 효력이 없음":"무효인 법률행위는 사후에 추인해도 효력이 생기지 않습니다.","무효인 친생자 출생신고도 입양의 실질적 요건을 갖추면 입양의 효력이 있고, 그 경우 친생자관계부존재확인의 소는 확인의 이익이 없음":"무효인 친생자 출생신고도 입양 요건을 실질적으로 갖췄다면 입양으로 인정되어 부존재확인의 소를 낼 이익이 없습니다.","무효임을 알거나 의심하면서 효과를 자기에게 귀속시키려는 의사가 있어야 묵시적 추인":"무효를 의심하거나 알면서 그 효과를 자기 것으로 하려는 뜻이 있어야 묵시적 추인이 됩니다.","무효임을 알고 추인하면 소급효 없이 새로운 법률행위로 봄(제139조)":"무효임을 알고 추인하면 소급 효력 없이 새 법률행위를 한 것으로 봅니다.","무효행위 전환은 적용 가능(제138조)":"무효행위의 전환은 불공정 법률행위에도 적용될 수 있습니다.","묵시적 합의해제는 쌍방에게 계약을 실현할 의사가 없거나 포기할 의사가 있다고 볼 정도여야 함":"묵시적 합의해제로 인정되려면 양쪽 모두 계약을 실현할 의사가 없거나 포기할 의사가 있다고 볼 정도여야 합니다.","물상보증인 소유 부동산이 먼저 경매되면 물상보증인은 변제자대위로 채무자 소유 부동산의 선순위 공동저당권을 취득하고, 물상보증인 부동산의 후순위저당권자는 그 위에 물상대위를 할 수 있음":"물상보증인 부동산이 먼저 경매되면 대위로 채무자 부동산의 선순위 공동저당권을 얻고, 그 부동산의 후순위저당권자는 물상대위를 합니다.","물상보증인의 구상 범위는 매각대금이 아니라 소유권을 잃은 때의 시가가 기준":"물상보증인의 구상은 매각대금이 아니라 소유권을 잃은 때의 시가를 한도로 합니다.","미성년자가 동의 없음을 이유로 취소하는 것도 신의칙 위반 아님":"미성년자가 법정대리인 동의가 없었음을 이유로 계약을 취소하는 것은 신의칙 위반이 아닙니다.","미성년자가 성년이 되어 후견감독이 끝난 때에는 종료신고를 하지 않음(가족관계등록법 제83조의5 제1항)":"미성년자가 성년이 되어 후견감독이 끝나면 따로 종료신고를 하지 않습니다.","미성년자 때 한 번 개명했다는 사실만으로 개명신청권 남용이 되지 않음":"미성년자 때 이미 한 번 개명했다는 이유만으로 개명신청권의 남용이 되지는 않습니다.","미성년자를 입양하려면 가정법원의 허가가 필요하고, 피성년후견인은 성년후견인의 동의와 가정법원의 허가를 받아 입양하거나 양자가 될 수 있으며 배우자 있는 사람은 배우자의 동의가 있어야 양자가 됨(제874조 제2항)":"미성년자 입양은 가정법원 허가, 피성년후견인은 후견인 동의와 허가, 배우자 있는 양자는 배우자 동의가 필요합니다.","미성년자 입양에는 가정법원 허가서를, 부모 동의를 갈음하는 심판이 있으면 그 심판서를 첨부(가족관계등록법 제62조)":"미성년자 입양에는 가정법원 허가서를, 부모 동의를 대신하는 심판이 있으면 그 심판서를 붙입니다.","미성년후견 개시신고는 미성년후견인이, 경질신고는 후임자가 각각 취임일부터 1개월 안에 함(가족관계등록법 제80조, 제81조)":"미성년후견 개시신고는 미성년후견인이, 경질신고는 후임자가 각각 취임일부터 1개월 안에 합니다.","반사회적 이중매매는 절대적으로 무효라서 제2매수인에게서 산 제3자도 선의를 내세워 유효 주장 불가":"반사회적 이중매매는 누구에게나 무효여서 두 번째 매수인에게서 산 제3자도 선의를 내세워 유효를 주장할 수 없습니다.","반환할 금전에는 받은 날부터 이자를 붙임":"돌려줄 금전에는 받은 날부터 이자를 붙여야 합니다.","반환할 금전에 법정이자를 붙일 필요도 없음":"합의해제로 반환할 금전에는 법정이자를 붙일 필요도 없습니다.","받은 것이 금전이면 소비했는지와 관계없이 현존하는 것으로 추정되고, 악의는 이익 보유에 법률상 원인이 없음을 인식한 것을 말하며 주장하는 쪽이 증명":"받은 것이 금전이면 소비했더라도 현존하는 것으로 추정되고, 악의란 이익 보유에 법률상 원인이 없음을 안 것으로 주장하는 쪽이 증명합니다.","발생하지 않는 것으로 확정된 때에도 이행해야 한다고 보는 것이 합리적이면 불확정기한":"그 사실이 영영 일어나지 않기로 확정되어도 이행해야 한다고 보는 것이 합리적이면 불확정기한입니다.","배액은 이행제공만 하면 되고 상대방이 받지 않아도 공탁할 필요 없음":"배액은 이행을 제공하기만 하면 충분하고 상대방이 안 받아도 공탁까지 할 필요는 없습니다.","법률행위 내용의 중요부분에 착오가 있으면 취소 가능":"계약 내용의 핵심 부분을 잘못 알고 의사표시를 했다면 그 의사표시를 취소할 수 있습니다.","법원은 손해배상에 갈음하거나 함께 명예회복에 적당한 처분을 명할 수 있지만(제764조) 사죄광고는 허용되지 않으며 법인의 명성·신용 훼손에도 비재산적 손해배상을 해야 함":"명예회복에 적당한 처분은 명할 수 있지만 사죄광고는 허용되지 않고, 법인의 명성·신용이 훼손되어도 비재산적 손해를 배상해야 합니다.","법원은 원고가 구하는 방법에 구애받지 않지만 분할청구자들이 원하지 않는데 그들을 여전히 공유로 남기는 분할은 할 수 없고, 상속재산은 공유물분할이 아니라 상속재산분할심판으로 나눔":"법원은 원고가 구한 방법에 얽매이지 않지만 공유를 원치 않는 청구자를 공유로 남기는 분할은 못 하고, 상속재산은 따로 분할심판으로 나눕니다.","법인을 실질적으로 운영하며 사실상 대표하는 사람도 대표자로 등기되었는지와 관계없이 대표자":"법인을 실제로 운영하며 사실상 대표하는 사람은 대표자로 등기되지 않았어도 대표자로 취급합니다.","법정지상권자가 등기 없이 건물을 팔면 지상권도 넘기기로 한 것으로 보아 양수인은 순차 대위로 설정·이전등기를 구할 수 있고, 대지소유자가 그 양수인에게 건물철거를 구하는 것은 신의칙상 허용되지 않음":"법정지상권자가 등기 없이 건물을 팔면 지상권도 같이 넘긴 것으로 보고, 양수인에게 대지소유자가 철거를 구하는 것은 신의칙상 허용되지 않습니다.","변제할 정당한 이익이 있는 사람은 변제로 당연히 채권자를 대위하는데(제481조), 이는 사실상이 아닌 법률상 이해관계를 말함":"변제할 정당한 이익이 있는 사람은 변제하면 당연히 채권자를 대위하며, 여기서 이익은 사실상이 아니라 법률상 이해관계를 말합니다.","보고적 신고에는 출생증명서 등을 대신해 거주국에 신고한 사실을 증명하는 서면을 붙일 수 있음":"보고적 신고에서는 출생증명서 대신 현지에 신고했음을 증명하는 서면을 붙여도 됩니다.","보존등기 명의인 아닌 사람이 사정받았거나":"보존등기 명의인이 아닌 사람이 토지 사정을 받았다고 밝혀져도 추정력이 깨집니다.","보존등기 명의인이 건물을 신축하지 않은 것으로 밝혀지면 추정력 깨짐":"보존등기 명의인이 건물을 새로 지은 사실이 없다고 드러나면 추정력이 깨집니다.","보존행위는 공유자 각자가 할 수 있어(제265조 단서) 제3자 명의 원인무효등기 전부의 말소를 구할 수 있지만 자기 지분이 침해된 공유자만 할 수 있고 다른 공유자의 지분권을 대신 주장하는 것은 보존행위가 아님":"보존행위는 공유자 각자가 하지만, 자기 지분이 침해된 공유자만 말소를 구할 수 있고 남의 지분권을 대신 주장할 수는 없습니다.","보증은 기명날인이나 서명이 있는 서면으로 해야 효력이 있는데(제428조의2), 기명날인은 타인이 대행해도 되지만 서명은 보증인이 직접 해야 함":"보증은 서면이 필수이며, 기명날인은 남이 대신할 수 있으나 서명은 보증인이 직접 해야 유효합니다.","본인, 배우자, 직계혈족은 증명서 교부를 청구할 수 있고 대리인은 위임을 받아야 하며 국가·지방자치단체의 직무상 문서 신청, 소송·비송·민사집행 절차상 필요 등은 예외로 청구할 수 있음(법 제14조 제1항)":"증명서 교부는 본인·배우자·직계혈족이 청구하고 대리인은 위임이 필요하며, 국가기관의 직무상 문서 신청이나 소송 절차상 필요도 예외로 허용됩니다.","본인의 사망, 실종선고·부재선고, 국적 이탈·상실이 있으면 등록부를 폐쇄하고(법 제11조 제2항), 이중 작성, 착오·부적법 작성, 정정된 등록부를 재작성하는 경우도 같음(규칙 제17조 제2항)":"본인의 사망, 실종선고·부재선고, 국적 이탈·상실이 있으면 등록부를 폐쇄하며, 이중 작성이나 착오 작성 등의 경우에도 폐쇄합니다.","본인이 청구하면 신청서를 쓰지 않아도 되고(영문증명서 제외), 상속인 범위 확인을 위한 사람은 정당한 이해관계인(규칙 제19조)":"본인이 청구하면 신청서를 쓰지 않아도 되고, 상속인 범위 확인을 하려는 사람은 정당한 이해관계인입니다.","부가 인지하지 않은 혼인 외 자녀도 부의 성과 본을 알면 따를 수 있음":"아버지가 인지하지 않았어도 혼인 외 자녀가 부의 성과 본을 안다면 따를 수 있습니다.","부가 혼인 외 자녀를 친생자로 출생신고하면 인지의 효력, 가정법원은 직권 조사 가능(가족관계등록법 제57조)":"부가 혼인 외 자녀를 친생자로 출생신고하면 인지의 효력이 생기고, 가정법원은 직권으로 조사할 수 있습니다.","부관 사실이 발생하지 않으면 채무를 이행하지 않아도 된다고 보는 것이 합리적이면 조건":"부관의 사실이 일어나지 않으면 이행하지 않아도 된다고 보는 것이 합리적일 때 그 부관은 조건입니다.","부동산 매수인이 피담보채무를 인수하고 대금에서 공제하기로 한 것은 원칙적으로 이행인수":"부동산을 산 사람이 피담보채무를 맡고 매매대금에서 빼기로 했다면 대개 이행인수입니다.","부동산 시가에 관한 착오는 동기의 착오일 뿐":"부동산 시가를 잘못 안 것은 계약의 동기에 관한 착오에 해당할 뿐입니다.","부동산실명법을 위반한 양자간 명의신탁에서 소유권은 신탁자에게 남아 신탁자가 등기말소나 진정명의회복을 구함":"양자간 명의신탁이 실명법에 위반되면 소유권은 신탁자에게 있어 말소나 진정명의회복을 구합니다.","부동산에 부합한 물건은 부동산 소유자가 취득하고 권원에 의해 부속된 것은 예외지만(제256조), 분리 복구가 불가능해 독립성을 잃었다면 권원이 있어도 부동산 소유자에게 귀속":"부합물은 원칙적으로 부동산 소유자가 가지고, 권원 있는 부속물은 예외이나 독립성을 잃었다면 소유자에게 귀속됩니다.","부득이한 사유 없이 상대방에게 불리한 시기에 해지하면 손해배상":"부득이한 사유도 없이 상대에게 불리한 때 위임을 끝내면 손해를 물어 주어야 합니다.","부란에 부의 성명은 기록하지 않음(가족관계등록규칙 제56조)":"이 경우 등록부의 부란에는 부의 성명을 기록하지 않습니다.","부모가 협의로 친권자를 정하면 1개월 안에 신고, 한쪽이 신고할 때는 이를 증명하는 서면을 붙임(가족관계등록법 제79조 제1항)":"부모가 협의로 친권자를 정하면 1개월 안에 신고하며, 한쪽이 신고할 때는 협의를 증명하는 서면을 붙입니다.","부모의 동의서는 요구하지 않음":"성별정정에서 부모의 동의서는 요구하지 않습니다.","부모의 양육의무는 자녀 출생과 동시에 생기므로 양육한 일방은 과거 양육비도 상대방에게 분담을 청구할 수 있고, 인지판결 확정 전의 양육비도 같음":"부모의 양육의무는 자녀 출생 때부터 생기므로 혼자 양육한 쪽은 과거 양육비의 분담도 청구할 수 있고, 인지판결 확정 전의 양육비도 같습니다.","부부간 과거 부양료는 부양을 청구해 상대방이 지체에 빠진 뒤의 것만 청구할 수 있음":"부부 사이의 과거 부양료는 부양을 청구해 상대가 지체에 빠진 이후 몫만 받을 수 있습니다.","부부간 부양은 1차 부양의무이고 부모의 성년 자녀 부양은 생활에 여유가 있음을 전제로 하는 2차 부양의무이며, 2차 부양의무자가 먼저 부양했다면 1차 부양의무자에게 상환을 청구할 수 있음":"부부 사이 부양이 1차, 여유 있을 때 성년 자녀를 돌보는 부모 부양이 2차이며, 먼저 부양한 2차 의무자는 1차 의무자에게 상환을 청구합니다.","부수적 채무의 불이행으로는 계약 목적을 달성할 수 없거나 특약이 있을 때에만 해제 가능":"계약의 부수적 채무를 이행하지 않은 경우에는 계약 목적을 이룰 수 없거나 특약이 있을 때에만 해제할 수 있습니다.","부의 등록기준지나 주소지 가정법원의 확인을 받아 신고 가능":"이때는 부의 등록기준지나 주소지 가정법원의 확인을 받아 출생신고를 할 수 있습니다.","부진정연대채무자 1인이 상계하면 채권자가 다른 채무자의 존재를 알았는지와 관계없이 소멸한 채무 전액이 다른 채무자에게도 효력이 있음":"부진정연대채무자 한 명의 상계는 채권자가 다른 채무자를 알았는지와 상관없이 소멸한 전액이 모두에게 효력이 있습니다.","부합으로 손해를 입은 사람의 보상청구(제261조)는 부당이득 요건까지 갖춰야 함":"부합으로 손해를 본 사람이 제261조로 보상을 구하려면 부당이득의 요건도 갖춰야 합니다.","분할협의는 공동상속인 전원이 참여해야 하지만 순차로 해도 되고, 친권자와 미성년 자녀 여럿이 협의할 때는 자녀마다 특별대리인을 선임해야 함":"협의는 전원 참여가 필요하나 순서대로 해도 되고, 친권자와 미성년 자녀 여럿이 함께하면 자녀마다 특별대리인이 필요합니다.","불공정한 법률행위는 추인해도 유효가 되지 않음":"불공정한 법률행위는 나중에 추인하더라도 유효해지지 않습니다.","불법행위 손해배상채무는 최고 없이 성립과 동시에 지체가 되고, 반환시기 약정이 없는 소비대차는 상당한 기간을 정해 최고한 뒤 그 기간이 지나야 지체가 됨":"불법행위 배상채무는 성립과 동시에 지체되고, 반환시기 없는 소비대차는 상당 기간을 정해 최고한 뒤에야 지체됩니다.","불법행위와 손해 발생 사이에 간격이 있으면 손해가 발생한 때가 손해액 산정과 지연손해금 기산의 기준이고, 예상할 수 없던 후발손해는 판명된 때가 기준":"손해가 불법행위와 시간차를 두고 생기면 손해가 발생한 때가 손해액 산정과 지연손해금 기산의 기준입니다.","불이익을 받을 당사자가 신의칙에 반해 조건 성취를 방해하면 상대방은 성취를 주장 가능":"조건 성취로 불이익을 입을 당사자가 신의칙에 어긋나게 방해하면 상대방은 성취된 것으로 주장할 수 있습니다.","비공개 심문과 직권탐지, 등록부정정허가에 대한 항고는 기간 제한 없는 통상항고":"심문은 비공개로 하고 법원이 직권으로 사실을 탐지하며, 정정허가에 대한 항고는 기간 제한이 없습니다.","비법인사단이 타인의 채무를 보증하는 것은 총유물의 관리·처분이 아님":"남의 채무를 비법인사단이 보증하는 일은 총유물의 관리나 처분에 해당하지 않습니다.","비석 등 제구를 설치·관리할 권한은 제사주재자에게 있음":"비석 같은 제구를 설치하고 관리할 권한은 제사주재자에게 있습니다.","사건본인의 등록기준지 관할 가정법원의 허가를 받아 신청(가족관계등록법 제104조, 제105조)":"사건본인의 등록기준지를 관할하는 가정법원의 허가를 받아 신청해야 합니다.","사건 자체를 말소할 때만 기록 전체에 선을 하나 그음(가족관계등록규칙 제66조)":"선을 하나 긋는 방식은 사건 자체를 말소할 때에만 쓰고, 이 경우 기록 전체에 긋습니다.","사망신고는 동거하는 친족이 의무자":"사망신고는 동거하는 친족이 의무자로서 해야 합니다.","사무관리는 타인의 사무를 타인을 위한 의사로 처리해야 하는데 이 의사는 자기 이익을 위한 의사와 함께 있어도 되고 외부에 표시하거나 관리 당시 확정될 필요가 없음":"사무관리의 의사는 자기 이익을 위한 의사와 함께 있어도 되고, 밖으로 표시하거나 관리 당시 확정될 필요가 없습니다.","사무집행 관련성은 외형상 객관적으로 판단하고, 업무와 시간적·장소적으로 근접하거나 동기가 업무와 관련되면 인정":"사무집행 관련성은 외형을 기준으로 객관적으로 판단하며, 업무와 시간·장소가 가깝거나 동기가 업무와 관련되면 인정됩니다.","사생활 침해 등 부당한 목적이 분명하면 시·읍·면의 장은 교부를 거부할 수 있음(법 제14조 제4항)":"사생활 침해 같은 부당한 목적이 분명하면 시·읍·면의 장은 증명서 교부를 거부할 수 있습니다.","사실혼 배우자 일방이 사망한 뒤 확정된 사실상혼인관계존재확인 판결로는 혼인신고 불가":"사실혼 배우자 한쪽이 죽은 뒤 확정된 사실상혼인관계존재확인 판결로는 혼인신고를 할 수 없습니다.","사실혼이 일방의 사망으로 끝나면 생존자에게 재산분할청구권이 없음":"사실혼이 한쪽의 사망으로 끝나면 살아남은 사람에게는 재산분할청구권이 없습니다.","사용관계는 유효한 고용이 아니어도 객관적으로 지휘·감독해야 할 관계면 인정되어, 명의대여자, 업무를 동업자 1인에게 맡긴 다른 동업자, 노무도급의 도급인도 사용자책임을 짐":"유효한 고용이 아니어도 객관적으로 지휘·감독할 관계가 있으면 사용관계가 인정되어 명의대여자나 노무도급의 도급인도 사용자책임을 집니다.","사임한 이사도 후임 이사가 선임될 때까지 직무 계속 가능":"이사직을 사임했더라도 후임 이사가 뽑힐 때까지는 직무를 이어서 할 수 있습니다.","사해성은 처분행위 당시를 기준으로 행위마다 따로 판단하고, 정지조건부 행위도 계약 당시, 가등기 후 본등기는 가등기 원인행위 당시가 기준":"사해성은 행위마다 처분 당시로 따로 보고, 정지조건부 행위는 계약 당시, 가등기 후 본등기는 가등기 원인행위 당시를 봅니다.","사해행위 전에 성립한 채권이면 그 뒤 양수한 사람도 취소권을 행사할 수 있고 대항요건을 사해행위 뒤에 갖춰도 됨":"사해행위 전에 생긴 채권을 나중에 양수한 사람도 취소권을 행사할 수 있고 대항요건은 사후에 갖춰도 됩니다.","사해행위취소로 건물 양도만 취소되어 등기가 말소된 경우도 소유자가 달라진 경우에 해당하지 않음":"사해행위취소로 건물 양도만 취소돼 말소됐다면 소유자가 달라진 것이 아닙니다.","상계는 의사표시로 하고 조건·기한을 붙이지 못하며(제493조 제1항), 소급효는 정산 기준 시점을 상계적상 때로 돌리는 것일 뿐":"상계는 의사표시로 하며 조건이나 기한을 붙이지 못하고, 소급효란 정산 기준 시점을 상계적상 때로 돌리는 것일 뿐입니다.","상대방에게 이를 이용하려는 폭리 의사가 있어야 함":"상대방에게도 이런 상황을 이용하려는 폭리 의사가 있어야 불공정 법률행위가 됩니다.","상대방은 임차권 소멸 당시의 토지소유자":"매수청구의 상대방은 임차권이 소멸한 당시의 토지소유자입니다.","상대방은 특정된 1인이어야 함":"수리불가신고의 상대방은 특정된 한 사람이어야 합니다.","상대방이 대리권 없음을 알았거나 알 수 있었을 때 책임 없음":"상대방이 대리권 없음을 알았거나 알 수 있었던 경우에는 무권대리인이 책임지지 않습니다.","상대방이 착오를 알고 이용했다면 중대한 과실이 있어도 취소 가능":"상대방이 착오를 알면서 그것을 이용했다면 표의자의 중대한 과실은 문제가 되지 않아 취소할 수 있습니다.","상대방이 한 번 이행을 제공했어도 계속하지 않으면 항변권은 소멸하지 않음":"상대가 이행을 한 번 제공했다가 이어 가지 않으면 동시이행 항변권은 없어지지 않습니다.","상속개시 전에 한 상속포기 약정에 반해 개시 후 상속권을 주장하는 것은 신의칙 위반 아님":"상속개시 전에 한 상속포기 약정과 달리 개시 후에 상속권을 주장해도 신의칙에 어긋나지 않습니다.","상속인은 상속개시 있음을 안 날부터 3개월 안에 가정법원에 신고해 포기할 수 있고(제1019조 제1항, 제1041조), 포기는 상속개시 때로 소급(제1042조)":"상속인은 상속개시를 안 날부터 3개월 안에 가정법원에 신고해 포기할 수 있고, 포기의 효력은 상속개시 때로 소급합니다.","상속재산 처분행위로 단순승인이 의제되는 것(제1026조 제1호)은 한정승인이나 포기 전의 처분에 한하고, 그 뒤의 처분은 은닉·부정소비에 해당할 때에만 단순승인이 됨(제3호)":"상속재산을 처분해 단순승인으로 보는 것은 한정승인·포기 전의 처분이고, 그 뒤에는 은닉·부정소비일 때만 단순승인이 됩니다.","상속채무 초과사실을 중대한 과실 없이 몰랐다는 특별한정승인의 요건은 상속인이 증명하고, 상속인이 미성년자면 법정대리인의 인식이 기준":"특별한정승인에서 상속채무 초과사실을 중과실 없이 몰랐다는 요건은 상속인이 증명하고, 미성년자면 법정대리인의 인식이 기준입니다.","상속포기는 사해행위취소의 대상이 아니지만 상속재산 분할협의는 대상이 되고, 포기 전에 상속재산을 처분하거나 채권을 추심하면 그 뒤의 포기는 효력이 없음":"상속포기는 사해행위취소 대상이 아니나 분할협의는 대상이고, 포기 전에 상속재산을 처분하거나 추심했다면 이후 포기는 소용없습니다.","상속회복청구권은 침해를 안 날부터 3년, 침해행위가 있은 날부터 10년이 지나면 소멸(제999조 제2항)":"상속회복청구권은 침해를 안 날로부터 3년, 침해행위일로부터 10년이 되면 사라집니다.","생존 중에 우송한 혼인신고서가 신고인 사망 후 도착해도 수리":"생존 중에 부친 혼인신고서가 신고인이 사망한 뒤 도착해도 수리합니다.","선의 수익자는 현존이익 한도에서, 악의 수익자는 받은 이익에 이자를 붙여 반환(제748조)":"선의 수익자는 남아 있는 이익만, 악의 수익자는 이자를 더한 이익 전부를 돌려줘야 합니다.","선의의 점유자는 과실을 취득하나 과실수취권이 있다고 오신할 만한 정당한 근거가 있어야 함(제201조 제1항)":"선의점유자가 과실을 가지려면 과실수취권이 있다고 오신할 만한 정당한 근거가 있어야 합니다.","선의이면 손해배상도 청구 가능(제570조)":"매수인이 선의이면 해제와 별도로 손해배상도 청구할 수 있습니다.","선이행의무도 이행기가 지나면 동시이행관계":"먼저 이행해야 하는 채무도 이행기가 지나면 상대방 채무와 동시이행 관계가 됩니다.","성본창설허가, 개명허가, 등록창설허가, 등록부정정허가 사건은 비송사건절차법 준용":"성본창설, 개명, 등록창설, 등록부정정을 허가하는 사건에는 비송사건절차법의 절차가 준용됩니다.","성전환자의 성별정정허가 사건에서 법원은 신청인을 반드시 심문":"성전환자의 성별정정허가 사건에서 법원은 반드시 신청인을 직접 심문해야 합니다.","성취 의제 시점은 방해가 없었다면 성취되었을 시점(제150조 제1항)":"방해가 없었다면 조건이 이루어졌을 시점을 성취 시점으로 간주합니다.","소가 각하·취하되어 판단 없이 끝나도 6개월 안에 재판상 청구를 하면 응소 시로 소급해 중단":"소가 각하되거나 취하되어도 6개월 안에 다시 재판상 청구를 하면 응소 당시로 소급해 시효가 중단됩니다.","소극재산이 적극재산보다 많아도 채무의 분담을 정하는 재산분할을 할 수 있고, 이미 발생한 공무원 퇴직연금수급권도 분할 대상이며 매월 연금 중 일정 비율을 지급하는 방식도 가능":"소극재산이 더 많아도 채무 분담을 정하는 재산분할을 할 수 있고, 이미 발생한 공무원 퇴직연금수급권도 분할 대상입니다.","소를 낸 사람이 사망했으면 배우자나 4촌 이내 친족이 신고 가능, 의무는 없음":"소를 낸 사람이 사망했다면 배우자나 4촌 이내 친족이 신고할 수 있으나 신고할 의무는 없습니다.","소를 제기한 사람이 판결확정일부터 1개월 안에 판결 등본과 확정증명서를 붙여 신청(가족관계등록법 제107조)":"소를 제기한 사람이 판결확정일부터 1개월 안에 판결 등본과 확정증명서를 붙여 신청합니다.","소멸시효는 법률행위로 배제·연장·가중 불가, 단축·경감은 가능(제184조 제2항)":"소멸시효는 법률행위로 늘리거나 없앨 수 없고 줄이는 것만 가능하다는 것이 제184조 제2항의 내용입니다.","소송행위에는 제109조 적용 없음":"소송절차상의 행위에는 착오 취소를 정한 제109조가 적용되지 않습니다.","소유권과 다른 물권이 한 사람에게 귀속하면 다른 물권은 소멸":"소유권과 다른 물권이 한 사람에게 모이면 그 다른 물권은 혼동으로 소멸합니다.","소유권과 분리해 물권적 청구권만 전소유자에게 남길 수 없음":"소유권을 남에게 넘기고 물권적 청구권만 전 소유자에게 남겨 둘 수는 없습니다.","소유권을 잃은 전소유자는 불법점유자에게 방해배제를 청구하지 못함":"소유권을 잃은 사람은 더 이상 불법점유자에게 방해를 없애라고 요구할 수 없습니다.","소유권이전등기를 넘겨준 매도인의 매매대금채권, 수급인에게 공급한 건축자재대금채권, 권리금반환채권, 계약명의신탁자의 매수자금 부당이득반환채권은 물건에 관하여 생긴 채권이 아니어서 유치권을 성립시키지 않음":"이전등기를 해 준 매도인의 대금채권이나 건축자재대금채권, 권리금반환채권 등은 그 물건에 관하여 생긴 채권이 아닙니다.","소유권이전등기 명의자는 제3자뿐 아니라 전소유자에 대해서도 적법한 원인으로 취득한 것으로 추정":"소유권이전등기를 받은 명의자는 제3자뿐 아니라 전 소유자와의 관계에서도 적법한 원인으로 취득했다고 추정됩니다.","소유자가 시효취득 등으로 소유권을 잃으면 말소청구권도 없어짐":"소유자가 시효취득 등으로 소유권을 잃으면 말소를 구할 권리도 함께 사라집니다.","손해배상 범위는 적당한 시기에 해지했다면 입지 않았을 손해에 한함":"배상 범위는 적당한 시기에 해지했더라면 입지 않았을 손해로 한정됩니다.","수급인 소유인 독립 건물의 기성부분이나 독립 건물이 되지 못하고 토지에 부합한 정착물에도 유치권을 행사할 수 없음":"수급인 소유 독립 건물의 기성부분이나 토지에 부합한 정착물은 유치권의 대상이 아닙니다.","수급인이 수리한 경우에는 도급인이 비용지출자":"수급인이 수리했다면 비용을 지출한 사람은 도급인으로 취급합니다.","수급인 하자담보책임의 1년은 재판 밖에서 행사해도 되는 기간(제670조)":"수급인 하자담보책임의 1년은 재판 밖의 청구로도 지킬 수 있는 기간입니다.","수익자·전득자의 선의는 그 자신이 객관적 자료로 증명해야 함":"수익자나 전득자가 선의라는 점은 그들 스스로 객관적 자료로 증명해야 합니다.","수임인은 무상이라도 선량한 관리자의 주의로 사무 처리(제681조)":"수임인은 보수 없이 일하더라도 선량한 관리자의 주의로 사무를 처리해야 합니다.","순차 이전등기의 말소청구는 통상공동소송이라 중간 명의자만 상대로 해도 됨":"순차로 이어진 이전등기의 말소청구는 통상공동소송이어서 중간 명의자만 피고로 삼아도 됩니다.","승인은 시효가 진행된 뒤에만 가능":"승인은 시효가 진행된 뒤에야 할 수 있습니다.","시·읍·면의 장과 그 대리인은 증명서 발급을 빼고 자기 또는 4촌 이내 친족의 등록사건을 처리하지 못함(법 제5조)":"시·읍·면의 장과 그 대리인은 증명서 발급 외에는 자기나 4촌 이내 친족의 등록사건을 처리할 수 없습니다.","시·읍·면의 장은 신청이 이유 있으면 처분을 바꾸고 이유 없으면 의견을 붙여 서류를 법원에 돌려보냄(가족관계등록법 제110조)":"시·읍·면의 장은 불복 신청이 옳으면 처분을 바꾸고, 그렇지 않으면 의견서를 붙여 서류를 법원에 되돌립니다.","시·읍·면의 장이 취임·퇴임하면 즉시, 사무소나 출장소를 옮기면 5일 안에, 행정구역·지번·도로명 등이 바뀌면 시행일 15일 전까지 감독법원에 보고(규칙 제7조, 제13조, 제14조)":"시·읍·면의 장이 취임·퇴임하면 즉시, 사무소를 옮기면 5일 안에, 행정구역 등이 바뀌면 시행 15일 전까지 감독법원에 보고합니다.","시효기간 중 등기명의자가 바뀌지 않았다면 기산점을 임의로 정할 수 있음":"시효 기간 중 등기명의자가 바뀌지 않았다면 점유 시작 시점을 기산점으로 임의로 골라도 됩니다.","시효완성 전에 상계적상이었던 채권은 완성 뒤에도 자동채권으로 쓸 수 있음(제495조)":"시효가 완성되기 전에 상계적상이었던 채권은 완성 후에도 자동채권으로 쓸 수 있습니다.","시효완성 후 등기 전에 먼저 이전등기를 받은 제3자에게는 시효취득으로 대항하지 못하지만 그 소유권 변동 시점을 새 기산점으로 다시 20년이 지나면 2차 취득시효를 주장할 수 있음":"시효완성 후 먼저 등기받은 제3자에게는 맞설 수 없고, 그 변동 시점부터 다시 20년이 지나면 2차 취득시효를 내세울 수 있습니다.","시효완성 후 승인했다고 바로 시효이익을 포기한 것으로 단정 불가":"시효가 끝난 뒤에 승인했다고 해서 곧바로 시효이익을 포기했다고 단정할 수는 없습니다.","시효이익의 포기에는 시효이익을 받지 않겠다는 효과의사 필요":"반면 시효이익을 포기하려면 시효이익을 받지 않겠다는 효과의사가 있어야 합니다.","시효중단 사유인 승인은 관념의 통지로 효과의사 불필요":"시효중단 사유인 승인은 사실을 알린다는 관념의 통지이므로 효과의사까지 필요하지는 않습니다.","시효취득을 원인으로 한 이전등기청구권은 점유가 계속되는 한 시효로 소멸하지 않고, 여기의 점유에는 간접점유도 들어감":"시효취득으로 인한 등기청구권은 점유를 계속하는 동안은 시효로 사라지지 않고, 간접점유도 이 점유에 해당합니다.","신고기간이 지나도 신고가 없으면 시·읍·면의 장이 신고의무자에게 최고":"신고기간이 지나도록 신고하지 않으면 시·읍·면의 장이 신고의무자에게 신고하라고 독촉합니다.","신고로 효력이 생기는 행위가 무효임이 명백하면 신고인이나 본인이 신청":"신고로 효력이 생기는 행위가 분명히 무효라면 신고인이나 본인이 정정을 신청할 수 있습니다.","신용카드 가입계약만으로는 기초 법률관계가 아니고, 특정물의 소유권이전등기청구권이나 이중양도로 생긴 손해배상채권도 피보전채권이 아님":"신용카드 가입계약은 기초 법률관계가 못 되고, 특정물 이전등기청구권과 이중양도의 손해배상채권도 보전 대상이 아닙니다.","신의칙 위반은 강행규정 위반이므로 당사자 주장이 없어도 법원이 직권으로 판단":"신의칙은 강행규정이라서 당사자가 내세우지 않아도 법원이 직권으로 위반 여부를 가립니다.","신청인이 대한민국 국적의 19세 이상 행위능력자인지 조사 가능":"법원은 신청인이 대한민국 국적을 가졌는지와 19세 이상 행위능력자인지를 조사할 수 있습니다.","실질적 이득이 없으면 반환의무가 없어, 종료 후 점유만 하고 사용·수익하지 않은 임차인은 부당이득을 반환하지 않음":"종료 후 점유만 했을 뿐 사용·수익은 하지 않은 임차인은 얻은 이득이 없어 부당이득을 돌려줄 필요가 없습니다.","심문은 비공개로 하고 상당하다고 인정하는 사람에게 방청 허가 가능":"심문은 공개하지 않고, 법원이 상당하다고 인정하는 사람에게는 방청을 허가할 수 있습니다.","아내가 혼인 중 임신한 자녀는 남편의 자녀로 추정되고(제844조), 제3자의 정자로 인공수정한 자녀에게도 추정이 미침":"혼인 중 아내가 임신한 자녀는 남편의 자녀로 추정되고, 타인의 정자로 인공수정한 경우에도 마찬가지입니다.","악의의 양수인에게서 다시 선의로 양수한 전득자도 보호됨":"악의의 양수인으로부터 다시 선의로 양수한 전득자도 보호받습니다.","압류 효력이 생긴 뒤 점유를 넘겨받았거나, 점유는 그 전에 받았어도 압류 뒤 공사를 완공해 공사대금채권을 취득했다면 매수인에게 대항하지 못함":"압류 효력이 생긴 뒤 점유를 넘겨받았거나 압류 뒤 공사를 마쳐 공사대금채권을 취득한 유치권자는 매수인에게 대항하지 못합니다.","양도금지 특약은 선의의 제3자에게 대항하지 못하지만(제449조 제2항), 판례는 악의뿐 아니라 중대한 과실로 모른 양수인에게도 대항할 수 있다고 보며, 그 악의·중과실은 특약을 주장하는 쪽이 증명":"양도금지 특약은 선의의 제3자에게 못 맞서지만 판례상 중과실 양수인에게는 맞설 수 있고, 악의·중과실은 특약을 주장하는 쪽이 증명합니다.","양도소득세를 줄이려고 대금을 낮춰 쓴 매매도 위반이 아님":"양도소득세를 줄이려고 매매대금을 낮춰 적은 경우에도 반사회질서 위반은 아닙니다.","양육비 감액 청구에서는 청구인의 소득·재산이 실질적으로 줄었는지를 심리하고, 심판으로 확정되어 이행기가 지난 양육비채권은 처분할 수 있음":"양육비 감액은 청구인 소득·재산이 실제로 줄었는지 심리하며, 이미 확정된 지난 양육비채권은 처분할 수 있습니다.","양자가 13세 미만이면 입양을 승낙한 법정대리인이 신고":"13세에 이르지 못한 양자를 입양하려면 입양을 승낙한 법정대리인이 대신 신고를 합니다.","업무집행자는 조합원 3분의 2 이상의 찬성으로 선임, 업무집행은 과반수로 정함(제706조)":"업무집행자는 조합원 3분의 2 이상의 찬성으로 뽑고, 업무집행 자체는 과반수로 정합니다.","업무집행 조합원의 배임으로 입은 손해는 조합의 손해라 조합원 개인이 배상을 구하지 못함":"업무집행 조합원의 배임으로 입은 손해는 조합 자체의 손해이므로 조합원 개인이 배상을 구할 수 없습니다.","연대채무자 1인에 대한 변제·대물변제·공탁·경개·상계는 채무 전부에 대해, 면제·혼동·소멸시효 완성은 그 부담부분에 한해 다른 연대채무자에게 효력이 있음":"연대채무자 한 명에 대한 변제·대물변제·공탁·경개·상계는 채무 전부에 효력이 있고, 면제·혼동·시효 완성은 그 부담부분에만 효력이 있습니다.","연대채무자 1인의 부동산 압류로 인한 시효중단은 다른 연대채무자에게 미치지 않음":"연대채무자 한 명의 부동산을 압류해 시효가 중단되더라도 그 효력이 다른 연대채무자에게는 미치지 않습니다.","영문증명서에는 본인·부모·배우자의 성명 등과 본인의 출생 및 현재 혼인에 관한 사항이 기록됨(규칙 제21조의3 제2항)":"영문증명서에는 본인·부모·배우자의 성명 등과 본인의 출생 및 현재 혼인 사항이 기록됩니다.","예금계약 체결의 대리권에 그 예금을 담보로 대출받을 권한은 불포함":"예금계약을 대리할 권한에는 그 예금을 담보로 돈을 빌릴 권한이 포함되지 않습니다.","예약 당시 재산 가액이 차용액과 이자의 합계를 넘어야 적용되고, 선순위 근저당권이 있으면 그 피담보채무를 뺀 가액으로 비교":"예약한 재산의 가액이 차용액과 이자 합계를 넘어야 하며, 선순위 근저당 피담보채무는 빼고 비교합니다.","예정이 있으면 특별손해까지 포함되어 초과분을 따로 청구하지 못하고, 채권자에게 과실이 있어도 과실상계 대신 감액 사유로 참작":"손해배상액이 예정되어 있으면 특별손해까지 포함되어 초과분을 따로 청구하지 못하고, 채권자의 과실은 과실상계가 아니라 감액 사유로 참작합니다.","오래 방치한 것만으로는 부족":"그저 오랫동안 계약을 방치했다는 사실만으로는 묵시적 합의해제로 보기에 부족합니다.","완성 당시 소유자에게 소유권이 다시 돌아오면 점유자는 그에게 시효완성을 주장할 수 있고, 시효완성 사실을 알고 매수한 제3자라도 소유자의 등기의무를 승계하지는 않음":"시효 완성 당시 소유자에게 소유권이 되돌아오면 점유자는 그에게 시효완성을 주장할 수 있습니다.","외국 방식으로 증서를 작성했으면 3개월 안에 재외공관의 장에게 그 등본을 제출해야 함(법 제35조 제1항)":"외국 방식으로 증서를 작성했다면 3개월 안에 재외공관의 장에게 그 등본을 제출해야 합니다.","외국법에 따라 개명했어도 한국 법원의 허가가 없으면 등록부에 기록할 수 없음":"외국법에 따라 이름을 바꿨더라도 한국 법원의 허가가 없으면 가족관계등록부에 기록하지 못합니다.","외국에 사는 한국인도 출생·사망 같은 보고적 신고 의무, 거주국 관공서 신고로 면제되지 않음":"해외 거주 한국인도 출생·사망 같은 보고적 신고를 해야 하며, 현지 관공서에 신고했다고 면제되지 않습니다.","외국에서 거행지 방식으로 혼인절차를 마쳤으면 한국에 혼인신고를 하지 않아도 혼인은 성립":"외국에서 현지 방식으로 혼인을 끝냈다면 한국에 따로 혼인신고를 하지 않아도 혼인은 유효합니다.","외국인 배우자의 본국법 방식만으로 한 혼인은 효력 없음":"외국인 배우자의 본국법 방식만 밟은 혼인은 한국에서 효력이 인정되지 않습니다.","외국인 부와 한국인 모의 혼인 외 자녀는 부가 인지하기 전에는 부의 성을 따를 수 없음":"외국인 아버지와 한국인 어머니 사이의 혼인 외 자녀는 인지 전에는 아버지의 성을 쓸 수 없습니다.","외국인의 이름은 원지음을 한글로 기록하고 한자를 함께 기록하지 않음":"외국인 이름은 원래 발음을 한글로 적으며 한자를 곁들이지 않습니다.","외국 판결에 따른 신고는 그 서면으로 확정판결과 집행판결을 대신하지 못함":"외국 판결에 따른 신고라면 그 서면만으로 확정판결과 집행판결을 갖춘 것으로 보지 못합니다.","원물반환이 원칙이고 불가능하거나 현저히 곤란할 때 가액배상을 하며 저당권이 말소된 경우 사실심 변론종결 당시 가액에서 피담보채무액을 뺀 범위에서 가액배상을 명함":"원물반환이 원칙이고 곤란하면 가액배상을 하되, 저당권이 말소됐다면 변론종결 때 가액에서 피담보채무액을 뺀 만큼 배상합니다.","원상회복은 현존이익과 선악을 묻지 않고 받은 이익 전부":"원상회복의무는 남아 있는 이익이나 선의·악의를 따지지 않고 받은 이익 전부를 돌려주는 것입니다.","원인 계약서가 위조로 증명되거나":"등기의 바탕이 된 계약서가 위조되었음이 증명되면 추정력이 깨집니다.","원인 없이 말소되어도 물권의 효력은 그대로":"등기가 원인 없이 지워지더라도 물권 자체의 효력은 사라지지 않습니다.","위법해서 폐쇄된 등록부는 정정할 수 없음":"위법하게 작성되어 폐쇄된 등록부는 정정 대상이 될 수 없습니다.","위약금 특약이 없으면 계약금은 손해배상액 예정이 아님":"위약금 특약이 없으면 계약금을 손해배상액의 예정으로 보지 않습니다.","위임은 각 당사자가 언제든지 해지 가능(제689조 제1항)":"위임은 당사자 누구든지 언제든지 해지할 수 있습니다.","위임인의 승낙이나 부득이한 사유 없이 복위임 불가(제682조 제1항)":"수임인은 위임인의 승낙이나 부득이한 사유 없이 다른 사람에게 복위임할 수 없습니다.","위탁물 횡령물은 도품·유실물이 아님(제250조)":"위탁물을 횡령한 경우는 도품이나 유실물이 아니므로 제250조의 특칙이 적용되지 않습니다.","유류분반환청구권, 구체화되지 않은 재산분할청구권, 재심의 소 제기는 대위의 목적이 되지 않음":"유류분반환청구권과 재심의 소 제기, 구체화 안 된 재산분할청구권은 대위로 행사할 수 없습니다.","유류분은 직계비속과 배우자가 법정상속분의 2분의 1, 직계존속이 3분의 1이고, 형제자매의 유류분은 2024. 9. 20. 개정으로 삭제(제1112조)":"직계비속·배우자의 유류분은 법정상속분의 2분의 1, 직계존속은 3분의 1이고, 형제자매 몫은 2024. 9. 20. 개정으로 폐지됐습니다.","유익비는 가액 증가가 현존할 때 회복자의 선택에 따라 지출금액이나 증가액 상환(제203조 제2항)":"유익비는 가치 증가가 남아 있을 때 회복자가 고르는 대로 지출액이나 증가액을 상환합니다.","유일한 재산을 우선변제권 있는 채권자에게 대물변제한 것은 원칙적으로 사해행위가 아니고, 변론종결 시 채무자가 자력을 회복했다면 취소권은 소멸하며 그 사실은 상대방이 증명":"유일한 재산을 우선변제권자에게 대물변제하면 원칙적으로 사해행위가 아니며, 자력 회복으로 취소권이 소멸했다는 점은 상대방이 증명합니다.","유책배우자의 이혼청구는 원칙적으로 허용되지 않지만 상대방도 혼인을 계속할 의사가 없거나 유책성을 상쇄할 만한 보호·배려가 있었거나 세월이 흘러 책임의 경중을 따지는 것이 무의미해진 경우에는 허용":"유책배우자의 이혼청구는 원칙적으로 안 되지만 상대방도 혼인을 이어 갈 마음이 없거나 세월이 흘러 책임의 경중이 무의미해진 경우에는 허용됩니다.","유치권의 점유는 직접점유든 간접점유든 되지만 채무자가 직접점유자이고 채권자가 간접점유하는 경우에는 유치권이 성립하지 않음":"유치권은 직접점유든 간접점유든 성립하지만, 채무자가 직접점유하고 채권자가 간접점유하는 경우에는 성립하지 않습니다.","유치권자는 채권 전부를 변제받을 때까지 유치물 전부에 권리를 행사하고, 이 불가분성은 목적물이 분할 가능하거나 여러 개여도 같음(제321조)":"유치권의 불가분성 때문에 채권 전부를 변제받을 때까지 목적물이 나뉘거나 여러 개여도 전부를 유치합니다.","의료기관의 의료인은 출생정보를 통보해야 함":"의료기관의 의료인은 출생정보를 통보할 의무가 있습니다.","의사능력이 있는 미성년자는 단독으로 개명허가 신청 가능":"의사능력이 있는 미성년자는 법정대리인 없이 혼자서 개명허가를 신청할 수 있습니다.","이 규정에 반해 임차인에게 불리한 약정은 효력 없음(제652조)":"이 규정에 어긋나 임차인에게 불리하게 정한 약정은 효력이 없습니다.","이때 조합원 수는 출자가액이 아니라 인원수로 셈":"이때 찬성 수는 출자한 금액이 아니라 조합원의 머릿수를 기준으로 헤아립니다.","이미 부담하는 채무의 변제에 붙인 부관은 특별한 사정이 없는 한 변제기를 유예한 불확정기한":"이미 진 채무의 변제에 붙은 부관은 특별한 사정이 없으면 변제기를 늦춰 준 불확정기한으로 봅니다.","이미 사망한 무등록자의 등록창설은 허용되지 않음":"이미 사망한 사람의 등록창설 신청은 받아 주지 않습니다.","이미 성취된 조건이 정지조건이면 조건 없는 법률행위, 해제조건이면 무효":"이미 이루어진 조건이 정지조건이면 조건 없는 법률행위가 되고, 해제조건이면 법률행위가 무효입니다.","이 보호규정은 합의해제에도 적용":"이 보호 규정은 합의해제를 한 경우에도 똑같이 적용됩니다.","이사가 여럿이면 정관에 다른 규정이 없는 한 사무집행은 이사의 과반수로 결정(제58조 제2항)":"이사가 여러 명일 때 정관에 다른 정함이 없으면 이사 과반수의 의견으로 사무를 결정합니다.","이사 기타 대표자는 대표기관을 말함(제35조)":"법인의 불법행위에서 이사 기타 대표자란 법인을 대표하는 기관을 뜻합니다.","이 이자는 부당이득반환의 성질":"돌려주는 돈에 붙는 이자는 부당이득을 반환하는 성질입니다.","이전 행위가 유효함을 전제로 후속행위를 했다는 것만으로 묵시적 추인 불성립":"앞선 행위가 유효하다고 보고 후속행위를 했다는 것만으로는 묵시적 추인으로 인정되지 않습니다.","이 제한은 대상자가 실제로 친양자로 입양되었는지와 관계없이 적용(규칙 제23조 제2항)":"이 제한은 대상자가 실제로 친양자로 입양되었는지와 상관없이 적용됩니다.","이중 등록부는 착오로 작성된 쪽을 폐쇄하고 당사자가 고를 수 없으며 폐쇄한 등록부의 증명서 우측 상단에는 폐쇄 표시를 함":"이중 등록부는 착오로 만든 쪽을 닫으며 당사자가 고를 수 없고, 닫은 등록부 증명서 우측 상단에 폐쇄 표시를 합니다.","이중매매가 무효가 되려면 제2매수인이 매도인의 배임행위에 적극 가담해야 함":"두 번째 매수인이 매도인의 배임에 적극 끼어들었을 때만 이중매매가 무효입니다.","이중양도된 양수인들 사이의 우열은 확정일자 있는 통지가 채무자에게 도달한 일시나 승낙의 일시로 정함":"채권이 이중으로 양도되면 확정일자 있는 통지의 도달 일시나 승낙 일시의 선후로 양수인 우열을 가립니다.","이해관계인은 시·읍·면의 장의 위법·부당한 처분에 대해 관할 가정법원에 불복 신청 가능(가족관계등록법 제109조 제1항)":"이해관계인은 시·읍·면의 장이 한 위법·부당한 처분에 대해 관할 가정법원에 불복 신청을 할 수 있습니다.","이행불능을 이유로 해제할 때도 동시이행관계에 있는 자기 채무를 제공할 필요 없음":"이행불능을 이유로 해제할 때는 동시이행 관계의 자기 채무를 제공하지 않아도 됩니다.","이행지체로 해제하려면 최고 필요":"이행지체를 이유로 계약을 해제하려면 먼저 상대방에게 최고해야 합니다.","이행판결이나 재판상 화해가 확정되어도 소유권이전등기를 마쳐야 소유권 취득":"이행판결이나 화해가 확정돼도 이전등기를 해야 비로소 소유자가 됩니다.","이혼소송 중 배우자 일방이 사망하면 소송은 종료하고 병합된 재산분할청구도 함께 종료":"이혼소송 중 한쪽이 사망하면 소송이 끝나고, 병합된 재산분할청구도 함께 끝납니다.","이혼위자료청구권은 행사상 일신전속권이어서 소 제기로 행사 의사가 명백해지면 양도·상속할 수 있고, 혼인이 해소된 때부터 3년이 지나면 시효로 소멸":"이혼위자료청구권은 소 제기로 행사 의사가 분명해지면 양도·상속이 되고, 혼인 해소 후 3년이 지나면 시효로 사라집니다.","이혼의사를 철회한 뒤 그 철회를 다시 철회해도 이혼신고는 수리하지 않음":"이혼 의사를 철회했다가 그 철회를 다시 철회해도 이혼신고를 받아 주지 않습니다.","이혼이 이미 성립한 뒤 사망하면 재산분할의무는 상속인에게 승계":"이혼이 끝난 뒤 한쪽이 죽으면 재산분할 의무가 그 상속인에게 넘어갑니다.","인도받은 매수인과 그 전매수인, 시효완성 점유자의 점유·사용은 부당이득이 아니고, 채무 없음을 알고 변제하면 반환을 구하지 못하는데 그 앎은 반환을 부인하는 쪽이 증명(제742조)":"인도받은 매수인과 전매수인, 시효완성 점유자의 사용은 부당이득이 아니며, 채무 없음을 알고 갚았다는 점은 반환을 막는 쪽이 증명합니다.","인지된 자녀는 부의 성과 본을 따름":"부의 인지를 받은 자녀는 아버지의 성과 본을 쓰게 됩니다.","인지신고 때 부모가 협의서를 내면 종전 성과 본을 그대로 쓸 수 있음":"인지신고를 할 때 부모가 협의서를 제출하면 이전의 성과 본을 유지할 수 있습니다.","인지 재판이 확정되면 소를 낸 사람이 확정일부터 1개월 안에 신고, 상대방도 신고 가능":"인지 재판 확정일부터 1개월 안에 소를 제기한 쪽이 신고하고, 상대방도 신고할 수 있습니다.","인터넷 발급은 본인, 배우자, 부모, 자녀가 신청할 수 있고 형제자매는 할 수 없으며(법 제14조의2 제2항), 중앙관리소의 전산운영책임관이 처리":"인터넷 발급은 본인, 배우자, 부모, 자녀만 신청하고 형제자매는 불가하며 중앙관리소의 전산운영책임관이 처리합니다.","인터넷 열람도 친양자가 성년이 된 뒤에만 할 수 있음":"인터넷으로 열람하는 것도 친양자가 성년이 된 뒤에만 가능합니다.","일반등록사항란에 사유를 기록":"정정한 사유는 일반등록사항란에 기록합니다.","일방이 위험을 떠안기로 한 사정은 사정변경에 들어가지 않음":"한쪽이 위험을 스스로 떠안기로 했던 사정은 사정변경의 범위에 들어가지 않습니다.","일부 대위변제자는 변제한 가액에 비례해 채권자와 함께 권리를 행사하고, 채무불이행에 따른 해지·해제는 채권자만 할 수 있음(제483조)":"일부 대위변제자는 변제액 비율로 채권자와 함께 권리를 행사하되, 해지·해제는 채권자만 할 수 있습니다.","일부만 받았어도 배액의 기준은 실제 받은 금액이 아니라 약정 계약금":"계약금 일부만 받았다면 배액 상환의 기준은 받은 금액이 아닌 약정한 계약금입니다.","일부무효이면 전부 무효가 원칙":"법률행위의 일부만 무효라면 원칙적으로 법률행위 전부가 무효입니다.","일부 지분에 설정된 저당권은 분할 뒤 분할된 각 부동산에 종전 지분 비율대로 존속":"공유지분 일부에 설정된 저당권은 분할 후에도 나뉜 각 부동산에 종전 지분 비율대로 남습니다.","일부청구임을 명시한 소는 그 일부만 중단":"일부청구라고 밝히고 낸 소는 청구한 그 부분에 한해서만 시효가 중단됩니다.","일신전속적 권리는 대위할 수 없음(제404조 제1항 단서)":"일신전속적 권리는 채권자가 대신 행사할 수 없다는 것이 제404조 제1항 단서입니다.","임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있어야 복대리인 선임 가능(제120조)":"임의대리인이 복대리인을 선임하려면 본인의 승낙이나 부득이한 사유가 있어야 합니다.","임차인이 원상복구를 약정했다면 비용상환청구권을 미리 포기한 것이어서 유치권을 주장할 수 없음":"원상복구를 약정한 임차인은 비용상환청구권을 미리 포기한 셈이라 유치권을 내세울 수 없습니다.","입양신고에는 증인 연서 불필요":"입양신고에는 증인의 연서가 필요하지 않습니다.","입양이 취소되거나 파양되면 입양 전 친족관계가 부활하지만 취소의 효력은 소급하지 않음(제908조의7)":"입양이 취소되거나 파양되면 입양 전 친족관계가 되살아나지만, 취소의 효력은 소급하지 않습니다.","입양 전 친족관계는 친양자 입양이 확정된 때 종료하고, 협의파양은 인정되지 않으며 재판상 파양만 할 수 있음":"친양자 입양이 확정되면 입양 전 친족관계는 끝나고, 협의파양은 안 되며 재판으로만 파양할 수 있습니다.","자기 명의 등기가 있었거나 법률로 소유권을 취득한 사람만 현재의 등기명의인을 상대로 청구 가능":"자기 명의 등기를 가진 적이 있거나 법률로 소유권을 취득한 사람만 현재 등기명의인에게 청구할 수 있습니다.","자기 토지에 분묘를 설치한 사람이 이장 특약 없이 토지를 양도해 분묘기지권을 취득하면 성립한 때부터 지료를 내야 함":"자기 토지에 분묘를 만든 사람이 이장 특약 없이 토지를 양도하면 분묘기지권이 생기고 성립한 때부터 지료를 내야 합니다.","자녀 전부가 포기하면 배우자와 손자녀 또는 직계존속이 공동상속하고, 그들이 없으면 배우자가 단독상속":"자녀가 모두 포기하면 배우자와 손자녀나 직계존속이 함께 상속하고, 그들이 없으면 배우자가 혼자 상속합니다.","잔대금 미지급 시 자동 해제 약정은 매도인이 이행을 제공해 매수인을 지체에 빠뜨려야 해제":"매수인이 잔대금을 안 내면 자동으로 풀린다는 약정도 매도인이 먼저 이행을 제공해 지체시켜야 효과가 있습니다.","장래 사정에 대한 예측이 빗나간 것은 착오가 아님":"앞날의 일을 예상했는데 어긋났다고 해서 그것을 착오라고 하지는 않습니다.","장래 채권은 미리 승인 불가, 이행인수인의 승인은 효력 없음":"아직 생기지 않은 장래 채권은 미리 승인할 수 없고, 이행인수인이 한 승인도 효력이 없습니다.","재산분할청구권은 이혼한 날부터 2년이 지나면 소멸하고(제839조의2 제3항), 이 기간은 그 안에 심판을 청구해야 하는 제척기간으로서 법원이 직권으로 조사":"재산분할청구권은 이혼한 날부터 2년이 지나면 소멸하고, 이 기간은 법원이 직권으로 조사하는 제척기간입니다.","재외국민은 관할 재외공관의 장에게 신고할 수 있고(법 제34조), 재외공관의 장은 수리한 서류를 1개월 안에 외교부장관을 거쳐 가족관계등록관에게 보냄(법 제36조 제1항)":"재외국민은 재외공관의 장에게 신고하고, 공관의 장은 접수한 서류를 1개월 안에 외교부장관을 거쳐 등록관에게 보냅니다.","재판상 분할은 현물분할이 원칙이고, 현물로 나눌 수 없거나 가액이 현저히 줄 염려가 있을 때 경매를 명함(제269조 제2항)":"재판으로 분할할 때는 현물분할이 원칙이며, 나눌 수 없거나 가치가 크게 줄 염려가 있으면 경매를 명합니다.","재판 확정 후 새로 발견된 재산의 추가 분할청구도 이 2년 안에 해야 함":"재판이 확정된 뒤 새로 발견된 재산을 추가로 분할해 달라는 청구도 이 2년 안에 해야 합니다.","저당권과 함께 담보가치 유지를 위해 설정한 지상권은 피담보채권이 변제로 소멸한 경우뿐 아니라 시효로 소멸한 경우에도 부종해 소멸":"저당권과 함께 담보가치 유지를 위해 설정한 지상권은 피담보채권이 시효로 소멸해도 부종성에 따라 같이 소멸합니다.","저당권 설정 뒤에 점유를 취득해 성립한 유치권도 저당권자에게 주장할 수 있음":"저당권 설정 뒤에 점유를 취득해 유치권이 성립했더라도 그 유치권을 저당권자에게 주장할 수 있습니다.","저당권을 설정해 준 채무자나 물상보증인이 목적물을 시효취득해도 저당권은 소멸하지 않고, 양도담보권설정자는 시효취득을 이유로 담보 목적 등기의 말소를 구하지 못함":"채무자나 물상보증인이 저당 부동산을 시효취득해도 저당권은 없어지지 않고, 양도담보 설정자는 시효취득을 이유로 말소를 구하지 못합니다.","전세권이 존속하는 동안 전세금반환채권만 분리해 확정적으로 양도할 수 없고, 소멸을 조건으로 한 장래 채권으로만 양도할 수 있음":"전세금반환채권은 전세권 존속 중에는 소멸을 조건으로 한 장래 채권으로만 양도됩니다.","전세권 존속기간은 10년을 넘지 못하고 넘으면 10년으로 줄어듦(제312조 제1항)":"전세권의 존속기간은 10년을 넘지 못하며, 더 길게 정해도 10년으로 줄어듭니다.","전세금은 제315조의 손해배상채권만 담보하므로 설정자는 다른 채권으로 상계해 물상대위권을 행사한 전세권저당권자에게 대항하지 못함":"전세금이 담보하는 것은 제315조의 손해배상채권뿐이라 다른 채권으로 상계해 물상대위권자에게 대항할 수 없습니다.","전세금은 현실로 주고받지 않고 기존 채권으로 갈음할 수 있고, 담보 목적으로 설정하고 목적물을 인도하지 않았어도 사용·수익을 완전히 배제한 것이 아니면 유효":"전세금은 기존 채권으로 대신 줄 수 있고, 인도 없이 담보 목적으로 설정해도 사용·수익을 완전히 배제하지 않았다면 유효합니다.","점유를 잃었다고 곧바로 소멸하지 않고 점유 상실 때부터 10년간 행사하지 않아야 소멸":"점유를 잃어도 바로 소멸하지 않고, 점유를 잃은 때부터 10년 동안 행사하지 않아야 소멸합니다.","점유를 잃으면 유치권은 소멸하고(제328조), 점유회수의 소에서 이겨 점유를 되찾아야 되살아남":"점유를 잃으면 유치권이 소멸하고, 점유회수의 소에서 이겨 점유를 되찾아야 유치권이 되살아납니다.","점유를 침탈당하면 반환과 손해배상 청구 가능":"점유를 빼앗긴 사람은 물건의 반환과 손해배상을 청구할 수 있습니다.","점유방해 제거청구의 1년은 반드시 소를 제기해야 하는 출소기간(제205조 제2항)":"점유방해 제거청구의 1년은 소를 반드시 제기해야 하는 출소기간입니다.","정관에 해임사유가 있으면 특별한 사정이 없는 한 그 밖의 사유로 해임 불가":"정관이 해임사유를 정해 놓았다면 특별한 사정이 없는 한 그 밖의 이유로는 이사를 해임할 수 없습니다.","정당한 이유가 있으면 감정인 평가로 유치물을 변제에 충당할 것을 법원에 청구할 수 있고 미리 채무자에게 통지해야 함(제322조 제2항)":"유치권자는 정당한 이유가 있으면 감정인 평가로 유치물을 변제에 충당하도록 법원에 청구할 수 있고 미리 채무자에게 통지해야 합니다.","정당한 이유는 대리행위 당시를 기준으로 판단(제126조)":"표현대리에서 정당한 이유가 있는지는 대리행위를 한 그 당시를 기준으로 판단합니다.","정당한 이유 없이 동거를 거부하는 배우자는 부양료를 청구할 수 없음":"정당한 이유 없이 동거를 피하는 배우자는 부양료를 달라고 할 수 없습니다.","정정 기록이 마쳐진 뒤에는 허가한 법원이 그 재판을 취소·변경할 수 없음":"정정 기록이 끝난 뒤에는 허가한 법원이라도 그 재판을 취소하거나 변경할 수 없습니다.","정정은 재판의 주문에 나타난 사항에 한해 가능":"허가에 의한 정정은 재판의 주문에 나타난 사항에 한해서만 할 수 있습니다.","정정할 부분에 새 사항을 기록하고 정정내용과 사유를 해당 사항란에 기록":"정정은 해당 부분에 새 내용을 적고 그 정정 내용과 사유를 같은 사항란에 남기는 방식입니다.","정지조건은 성취한 때부터 효력이 생기고 소급하지 않음":"정지조건은 조건이 이루어진 때부터 효력이 생기며 과거로 거슬러 올라가지 않습니다.","제109조 제1항은 임의규정이라 합의로 적용을 배제 가능":"당사자가 합의로 제109조 제1항을 적용하지 않기로 할 수 있는 이유는 이것이 임의규정이기 때문입니다.","제366조의 법정지상권은 저당권 설정 당시 토지 위에 건물이 있어야 하므로, 나대지에 저당권을 설정한 뒤 지은 건물에는 성립하지 않음":"저당권을 설정할 당시 토지 위에 건물이 있어야 제366조의 법정지상권이 생기므로, 나대지에 저당을 잡은 뒤 지은 건물에는 성립하지 않습니다.","제3자가 서류를 위조해 특정 상속인 명의로 상속등기를 했다면 그 명의인은 참칭상속인이 아님":"제3자가 서류를 위조해 만든 상속등기라면 그 명의인을 참칭상속인으로 볼 수 없습니다.","제3자가 신청한 경매에서는 매수인이 매각대금을 낸 때 확정":"남이 신청한 경매에서는 매수인이 대금을 낸 시점에 피담보채권이 정해집니다.","제3자는 허위표시로 생긴 외형을 토대로 새로운 이해관계를 맺은 사람":"허위표시로 만들어진 겉모습을 믿고 새로 이해관계를 맺은 사람이 여기서 말하는 제3자입니다.","제3자에 대한 반환청구권을 양도받아 대항요건을 갖추면 점유취득 요건 충족":"제3자에게 있는 물건의 반환청구권을 넘겨받아 대항요건을 갖추면 점유취득 요건을 채운 것입니다.","제3자와의 약정에 따라 타인의 사무를 처리한 것은 그 타인에 대한 사무관리가 아니고, 관리자는 사실상 이익을 얻은 제3자에게 직접 부당이득반환을 청구하지 못함":"제3자와의 약정에 따라 남의 사무를 처리했다면 그 타인에 대한 사무관리가 아니어서 이익 본 제3자에게 직접 부당이득 반환을 구하지 못합니다.","제3채무자는 채권자의 채무자에 대한 권리가 시효로 소멸했다는 항변은 하지 못하나, 그 권리의 발생원인이 무효이거나 변제로 소멸했다는 주장은 할 수 있음":"제3채무자는 시효 소멸 항변은 못 하나 권리의 발생원인이 무효이거나 변제로 소멸했다는 주장은 할 수 있습니다.","제840조의 각 호는 별개의 이혼사유여서 법원은 그 중 하나만 인정해도 청구를 받아들일 수 있음":"제840조의 호마다 독립된 이혼사유이므로 법원은 한 가지만 인정해도 이혼을 받아들일 수 있습니다.","제적부는 부활하지 않고 정정":"제적부는 다시 살리지 않은 채 그 자리에서 정정합니다.","제척기간에는 중단이 없고 기간 경과 자체로 권리 소멸":"제척기간은 중단이 없고 기간이 지나면 권리가 그대로 사라집니다.","제한물권이 있는 경우 매수인의 권리는 그 사실을 안 날부터 1년 안에 행사(제575조 제3항)":"제한물권이 붙어 있는 경우 매수인은 그 사실을 안 날부터 1년 안에 권리를 행사해야 합니다.","조건을 붙이려는 의사는 법률행위 내용으로 외부에 표시되어야 하지만 묵시적으로도 가능":"조건을 붙일 의사는 밖으로 표시되어야 법률행위 내용이 되지만 말없이 묵시적으로 표시해도 됩니다.","조건이 사회질서에 반하면 조건만이 아니라 법률행위 전부가 무효(제151조 제1항)":"조건이 사회질서에 어긋나면 조건만 빼는 것이 아니라 법률행위 전체가 무효가 됩니다.","조합계약은 해제·해지할 수 없고 해산청구, 탈퇴, 제명으로만 관계를 정리":"조합은 해제·해지가 안 되고 해산청구, 탈퇴, 제명으로 정리합니다.","조합원의 탈퇴권, 임대인의 해지권, 토지거래허가 협력의무 이행청구권은 대위할 수 있음":"조합원의 탈퇴권, 임대인의 해지권, 토지거래허가 협력의무 이행청구권은 채권자가 대신 행사해도 됩니다.","조합재산의 처분·변경은 조합의 업무집행 문제로서 제706조 제2항이 우선 적용되고, 합유자가 죽으면 상속인이 승계하지 않고 남은 합유자에게 귀속":"조합재산의 처분은 업무집행의 문제라 제706조 제2항이 먼저 적용되고, 합유자가 죽으면 남은 합유자들에게 귀속됩니다.","존속이 아니면 혈족도 입양할 수 있어 조부모가 손자녀를 입양할 수 있음":"존속이 아니면 혈족도 양자로 삼을 수 있어 할아버지·할머니가 손자녀를 입양할 수 있습니다.","종물은 주물 소유자 자신의 물건이어야 하고, 종물은 주물의 처분에 따른다는 제100조 제2항은 임의규정이라 종물을 빼고 처분하거나 따로 처분할 수 있음":"종물은 주물 주인의 것이어야 하고, 주물 처분에 따른다는 규정은 임의규정이라 따로 처분할 수 있습니다.","종중원의 자격 박탈·탈퇴나 종중 분열은 인정되지 않음":"종중원 자격을 박탈하거나 탈퇴하는 일, 종중이 갈라지는 일은 인정되지 않습니다.","종중총회 소집통지는 통지 가능한 모든 종중원에게 해야 하나 구두·전화나 다른 종중원을 거쳐도 가능":"종중총회 소집통지는 통지할 수 있는 모든 종중원에게 해야 하지만, 말이나 전화, 다른 종중원을 통한 전달도 허용됩니다.","주위토지통행권은 현재 토지 용법에 따른 범위에서만 인정되고 장래 이용까지 미리 대비해 정할 수 없으며 통로가 특정 장소로 고정되지 않음":"주위토지통행권은 현재 용법에 필요한 범위만 인정되며 장래 이용을 미리 정하지 못하고 통로도 고정되지 않습니다.","주채무자가 변제할 때 보증인이나 물상보증인이 있는 채무와 없는 채무 사이에는 변제이익의 차이가 없음":"보증인이나 물상보증인이 있는지 여부는 변제이익의 차이를 만들지 않습니다.","주채무자에 대한 시효중단은 보증인에게도 효력이 있으나(제440조), 보증채무의 시효중단은 주채무에 미치지 않고, 주채무가 시효로 소멸하면 보증채무도 소멸":"주채무에 대한 시효중단은 보증인에게도 미치나 반대는 아니며, 주채무가 시효로 소멸하면 보증채무도 소멸합니다.","주택임차권등기의 말소의무와 보증금반환의무는 동시이행관계가 아님":"주택임차권등기 말소의무와 보증금반환의무 사이에는 동시이행 관계가 성립하지 않습니다.","중도금을 약정일에 내지 않으면 계약을 무효로 한다는 특약은 불이행만으로 자동 해제":"중도금을 약정일에 안 내면 무효로 한다는 특약은 불이행 자체로 계약이 자동 해제된다는 뜻입니다.","증서 등본 제출 방식으로 기록할 수 있는 것은 창설적 신분행위가 성립한 경우뿐":"증서 등본을 제출해 기록할 수 있는 경우는 창설적 신분행위가 이미 성립한 때로 한정됩니다.","증여는 유증을 반환받은 뒤에야 청구할 수 있고(제1116조), 청구권은 상속개시와 반환할 증여·유증이 있음을 안 때부터 1년, 상속개시부터 10년이 지나면 시효로 소멸(제1117조)":"증여는 유증을 먼저 반환받은 뒤에야 청구할 수 있고, 청구권은 안 때부터 1년, 상속개시부터 10년이 지나면 시효로 소멸합니다.","증여재산은 상속개시 당시 시가로 평가하되, 상속개시 전에 처분·수용되었으면 처분 당시 가액에 물가변동률을 반영하고, 수증자가 자기 비용으로 성상을 바꿨으면 증여 당시 성상을 기준으로 함":"증여재산은 개시 당시 시가로 보되, 먼저 처분·수용됐다면 처분 당시 가액에 물가변동률을 곱하고 성상이 바뀌었다면 증여 당시 모습을 봅니다.","증인 연서가 빠진 채 수리되었어도 혼인은 유효, 수리 때 발견하면 거부":"증인 연서가 없는데 수리됐다면 혼인은 유효하지만, 수리 단계에서 알았다면 거부해야 합니다.","지료는 성립요건이 아니어서 약정이 없으면 무상 지상권":"지료는 지상권의 성립요건이 아니라서 약정하지 않으면 무상 지상권이 됩니다.","지명채권 양도는 양도인의 통지나 채무자의 승낙이 있어야 채무자와 제3자에게 대항할 수 있고, 제3자에게는 확정일자 있는 증서가 필요(제450조)":"지명채권 양도는 통지나 승낙으로 채무자와 제3자에게 대항하고, 제3자에게는 확정일자 있는 증서가 더 필요합니다.","지역권은 계속되고 표현된 것만 시효취득할 수 있고(제294조), 통행지역권은 요역지 소유자가 승역지에 통로를 개설해 사용한 상태가 계속되어야 함":"지역권은 계속되고 표현된 것만 시효취득할 수 있고, 통행지역권은 요역지 소유자가 통로를 직접 만들어 계속 사용해야 성립합니다.","지역권은 요역지 소유권에 부종해 이전하고 공유자 1인은 자기 지분에 관해 지역권을 소멸시키지 못함(제292조, 제293조)":"지역권은 요역지 소유권에 딸려 함께 넘어가고, 공유자 한 명이 자기 지분만 따로 지역권을 없앨 수는 없습니다.","지연손해금도 채권최고액 한도에서 전부 담보됨":"지연손해금도 채권최고액 한도 안에서 모두 근저당권이 담보합니다.","지연손해금률 약정은 손해배상액 예정이라 부당히 과다하면 감액할 수 있고(제398조 제2항), 감액 여부는 사실심 변론종결 당시를 기준으로 판단하며 위약벌에는 이 감액이 유추적용되지 않음":"지연손해금률 약정은 손해배상액 예정이라 지나치면 줄일 수 있고, 감액은 변론종결 당시로 판단하며 위약벌에는 유추되지 않습니다.","지정 없이 모든 채무에 부족한 금액을 변제하면 모든 채무를 승인":"채무가 여럿인데 지정 없이 부족한 금액을 갚았다면 모든 채무를 승인한 것이 됩니다.","진실한 사실로서 오로지 공공의 이익에 관한 것이면 위법성이 없고, 진실성은 중요 부분이 사실과 맞으면 인정":"진실한 사실을 오로지 공익을 위해 밝힌 경우는 위법하지 않으며, 중요 부분이 맞으면 진실하다고 봅니다.","진정명의회복을 원인으로 한 이전등기청구는 무효등기 말소청구와 목적과 성질이 같은 방해배제청구권":"진정명의회복 이전등기청구는 무효등기 말소청구와 같은 성질의 방해배제청구입니다.","진정상속인이 상속을 귀속원인으로 내세워 등기말소 등을 구하면 청구원인과 관계없이 상속회복청구이고, 참칭상속인에게서 양수한 제3자를 상대로 해도 이 기간이 적용되며, 사망 후 인지된 혼외자의 '안 날'은 인지판결 확정일":"상속을 이유로 한 등기말소 청구는 모두 상속회복청구여서 제척기간이 적용되고, 사망 후 인지된 혼외자의 안 날은 인지판결 확정일입니다.","질권설정자는 질권자 동의 없이 목적 채권을 소멸시키거나 이익을 해하는 변경을 하지 못하지만(제352조), 그 위반은 질권자에 대한 관계에서만 무효이고, 채권양도나 임대차의 묵시적 갱신은 여기 해당하지 않음":"질권설정자가 질권자 동의 없이 목적 채권을 없애거나 불리하게 바꾸면 질권자에게만 무효이고, 채권양도·임대차 묵시 갱신은 해당하지 않습니다.","차임연체 등 채무불이행으로 해지되면 청구 불가":"차임을 연체하는 등 채무불이행으로 계약이 해지된 경우에는 지상물 매수를 청구할 수 없습니다.","참칭상속인은 상속인이라고 믿게 하는 외관을 갖추거나 상속인이라 하며 상속재산을 점유하는 사람이고, 외관도 점유도 없이 상속인이라고 주장만 하는 사람은 해당하지 않음":"참칭상속인은 상속인처럼 보이는 외관을 갖추었거나 상속재산을 점유하는 사람이며, 외관도 점유도 없이 주장만 하는 사람은 해당하지 않습니다.","채권에는 배타성이 없어 제3자가 채권을 침해했다고 곧바로 불법행위가 되지는 않음":"채권은 배타적 권리가 아니어서 제3자가 침해했다는 사정만으로 곧장 불법행위가 되지는 않습니다.","채권이 가압류되어도 제3채무자는 이행기가 지나면 지체책임을 지고, 추심명령의 제3채무자는 추심금 청구를 받은 다음 날부터 지체책임을 짐":"채권이 가압류돼도 이행기가 지나면 제3채무자는 지체하며, 추심명령은 추심금 청구를 받은 다음 날부터 지체합니다.","채권자가 보전행위 외의 권리를 행사하고 채무자에게 통지하면 채무자는 그 권리를 처분해도 채권자에게 대항하지 못하지만(제405조), 채무자의 채무불이행을 이유로 제3채무자가 계약을 해제한 것은 대항할 수 있음":"통지받은 채무자가 권리를 처분해도 채권자에게 맞서지 못하나, 채무불이행을 이유로 한 제3채무자의 계약 해제에는 대항할 수 있습니다.","채권자가 피고로 응소해 권리를 주장하고 받아들여지면 재판상 청구 해당":"채권자가 피고로서 응소하며 권리를 주장해 인정받으면 재판상 청구로 보아 시효가 중단됩니다.","채권자는 제3채무자에게 자기에게 직접 급부하라고 청구할 수 있음":"대위하는 채권자는 제3채무자에게 자기에게 바로 주라고 요구할 수 있습니다.","채권자를 해함을 알면서 법규나 사회질서에 위반하는 위법한 행위로 채권자의 이익을 침해해야 불법행위가 되고, 위법성은 거래자유와 공공이익 등을 종합해 판단":"채권자를 해할 줄 알고 법규나 사회질서를 어겨 침해해야 불법행위이고, 위법성은 거래자유와 공공이익을 함께 따집니다.","채권자취소의 소는 수익자나 전득자를 피고로 하고 채무자는 피고가 될 수 없음":"채권자취소의 소는 수익자나 전득자를 상대로 하고 채무자를 피고로 삼을 수는 없습니다.","채권증서가 있으면 증서를 교부해야 질권이 성립하는데(제347조), 임대차계약서는 채권증서가 아님":"채권증서가 있는 채권을 질권의 목적으로 삼으려면 증서를 교부해야 하고, 임대차계약서는 이 채권증서가 아닙니다.","채무불이행 해지 요건을 갖추지 못한 해지 의사표시도 임의해지로서 효력":"채무불이행 해지의 요건을 못 갖춘 해지 의사표시도 임의해지로서의 효력은 인정됩니다.","채무자가 다른 채권자에게 정당하게 변제한 것을 요청한 행위는 위법하지 않음":"다른 채권자에게 정당하게 갚으라고 채무자에게 요청한 행위는 위법하지 않습니다.","채무자가 이미 그 권리를 재판상 행사했다면 패소가 확정되었어도 대위할 수 없고, 채무자가 사망했거나 실존하지 않으면 대위소송은 부적법":"채무자가 이미 재판에서 그 권리를 행사했으면 패소가 확정되었어도 대위가 안 되고, 채무자가 사망했거나 없으면 소가 부적법합니다.","채무자가 이의를 보류하지 않고 승낙하면 양도인에게 대항할 수 있던 사유로 양수인에게 대항하지 못하고, 통지만 있으면 통지를 받을 때까지 양도인에게 생긴 사유로 대항할 수 있음(제451조)":"이의 없이 승낙하면 양도인에게 주장하던 사유로 양수인에게 못 맞서고, 통지만 받았다면 통지 때까지의 사유로 맞설 수 있습니다.","채무자가 이행하지 않을 의사를 명백히 하면 이행기 전에도 최고·자기 이행제공 없이 해제":"채무자가 이행하지 않겠다고 명백히 밝히면 이행기 전에도 최고하거나 자기 이행을 제공하지 않고 곧바로 해제할 수 있습니다.","채무자가 회복된 부동산을 다시 처분하면 무권리자의 처분으로 무효이고 채권자는 그 등기의 말소를 구할 수 있음":"원상회복된 부동산을 채무자가 다시 팔면 무권리자의 처분으로 무효여서 채권자가 말소를 구할 수 있습니다.","채무자 겸 설정자와의 관계에서는 채권 전액을 갚아야 근저당권이 소멸하므로, 최고액과 비용만 공탁해서는 말소를 청구하지 못함":"근저당권을 지우려면 채권 전액을 갚아야 하므로 최고액과 비용만 공탁한 채 말소를 구할 수는 없습니다.","채무자 소유와 물상보증인 소유 부동산에 공동저당이 있고 동시배당하면 제368조 제1항은 적용되지 않고 채무자 소유 부동산 대가에서 먼저 배당":"채무자 소유와 물상보증인 소유 부동산이 함께 공동저당이고 동시배당할 때는 먼저 채무자 소유 부동산 대가에서 배당합니다.","채무자 승낙 없이 사용·대여·담보제공을 하지 못하나 보존에 필요한 사용은 할 수 있고(제324조 제2항), 이 경우에도 차임 상당 이득은 소유자에게 반환":"채무자 승낙 없이 사용·대여·담보제공은 안 되지만 보존에 필요한 사용은 가능하고, 이때도 차임 상당 이득은 소유자에게 돌려줍니다.","채무자 아닌 사람의 동산이 경매되어도 매각대금을 내고 인도받은 매수인은 선의취득 가능":"경매로 팔린 동산이 채무자 것이 아니어도 대금을 내고 넘겨받은 매수인은 소유권을 얻을 수 있습니다.","채무자와 인수인의 계약에 의한 면책적 채무인수는 채권자가 승낙해야 효력이 생기고, 승낙이나 거절은 채무자나 인수인에게 하며(제454조), 한 번 거절하면 다시 승낙해도 효력이 없음":"채무자와 인수인의 계약으로 하는 면책적 채무인수는 채권자의 승낙이 있어야 효력이 생기고, 한 번 거절하면 다시 승낙해도 효력이 없습니다.","채무초과 상태에서 상속재산분할협의로 자기 상속분을 포기하면 사해행위가 될 수 있지만 협의·심판으로 구체화되지 않은 재산분할청구권을 포기하는 것은 취소 대상이 아님":"채무초과 상태에서 상속분을 포기하면 사해행위가 될 수 있지만, 구체화되지 않은 재산분할청구권의 포기는 취소 대상이 아닙니다.","청산절차를 거치지 않은 본등기는 무효이지만 나중에 청산절차를 마치거나 선의의 제3자가 소유권을 취득하면 유효하게 됨":"청산절차 없이 한 본등기는 무효지만 이후 청산을 마치거나 선의 제3자가 소유권을 얻으면 유효해집니다.","총유물은 보존행위라도 소송을 하려면 사원총회 결의나 정관 절차를 거쳐야 함":"총유물에 대해서는 보존행위라도 소송을 하려면 사원총회 결의나 정관에서 정한 절차를 밟아야 합니다.","총회 결의를 거치지 않았어도 무효가 아님":"그래서 총회 결의를 거치지 않았더라도 그 보증이 무효가 되지는 않습니다.","최고한 뒤 감독법원의 허가를 받아 직권으로 출생 기록(가족관계등록법 제44조의3, 제44조의4)":"최고한 뒤에도 신고가 없으면 감독법원의 허가를 받아 직권으로 출생을 기록합니다.","추정을 깨려면 친생부인의 소로 해야 하고 친생자관계부존재확인의 소는 부적법하지만 장기간 해외 체류 등 동거가 없어 임신할 수 없는 사정이 외관상 명백하면 추정이 미치지 않아 부존재확인의 소로 다툴 수 있음":"추정은 친생부인의 소로 깨야 하지만, 장기 해외 체류 등으로 임신이 불가능함이 외관상 분명하면 추정이 안 미쳐 부존재확인의 소가 가능합니다.","출생신고는 출생 후 1개월 안에 함(가족관계등록법 제44조 제1항)":"출생신고는 출생 후 1개월 안에 해야 합니다.","출생신고서의 이름과 등록부의 이름이 다르면 개명이 아니라 정정 절차로 바로잡음":"출생신고서의 이름과 등록부의 이름이 어긋나면 개명 절차가 아니라 정정 절차로 바로잡아야 합니다.","출생신고일자를 입양신고일자로 기록, 파양판결로는 정정 불가":"이때 출생신고일자를 입양신고일자로 기록하며, 파양판결로는 이렇게 정정할 수 없습니다.","출생신고 전에 자녀가 죽었으면 출생과 사망을 함께 신고(가족관계등록법 제47조, 제51조)":"출생신고 전에 자녀가 죽었다면 출생과 사망을 함께 신고합니다.","출생신고하지 않은 모와 양친자관계존재확인 판결이 확정되면 친생자관계를 양친자관계로 정정":"친생자로 잘못 기록된 사이라도 양친자관계존재확인 판결이 확정되면 기록을 양친자관계로 정정합니다.","출생자가 제3자의 친생추정을 받고 있음이 밝혀지면 1개월 안에 출생신고와 등록부 정정을 신청(가족관계등록법 제57조 제4항)":"출생자가 제3자의 친생추정을 받고 있음이 밝혀지면 1개월 안에 출생신고와 등록부 정정을 신청합니다.","충당 지정이 없으면 이행기 도래, 변제이익, 이행기 선후 순으로 법정충당하고(제477조), 비용·이자·원본 순서(제479조)는 일방이 바꿀 수 없으나 합의나 묵시적 합의로는 달리 정할 수 있음":"충당 지정이 없으면 이행기, 변제이익, 선후 순으로 법정충당하고, 비용·이자·원본 순서는 일방이 바꾸지 못하나 합의로는 바꿉니다.","취소와 원상회복은 모든 채권자를 위해 효력이 있지만(제407조) 사해행위 뒤에 채권을 취득한 채권자는 포함되지 않고, 취소채권자에게 우선변제권이 생기지도 않음":"취소와 원상회복은 모든 채권자를 위해 효력이 있으나 사해행위 뒤에 채권을 얻은 채권자는 제외되고, 취소채권자에게 우선변제권도 생기지 않습니다.","취소원인을 안 날부터 1년, 법률행위가 있은 날부터 5년 안에 제기해야 하고(제406조 제2항), 취소원인을 안다는 것은 그 행위로 채권을 완전히 만족시킬 수 없게 된다는 것까지 아는 것":"취소원인을 안 날부터 1년, 행위일부터 5년 안에 제기하며, 안다는 것은 채권 만족이 불가능해졌음까지 아는 것입니다.","치료비 채권은 개개의 진료가 끝날 때마다 시효 진행, 퇴원 시부터 진행하는 것이 아님":"치료비 채권의 시효는 진료가 하나씩 끝날 때마다 따로 진행하고 퇴원 때부터 한꺼번에 흐르지 않습니다.","친생부인의 소는 사유를 안 날부터 2년 안에 제기해야 하고(제847조 제1항), 출생 후 친생자임을 승인한 사람은 다시 제기하지 못함(제852조)":"친생부인의 소는 사유를 안 날부터 2년 안에 제기해야 하며, 출생 후 친생자임을 승인한 사람은 다시 제기하지 못합니다.","친생부인의 소를 제기했어도 출생신고를 해야 함":"친생부인의 소를 제기했더라도 출생신고는 해야 합니다.","친양자는 3년 이상 혼인 중인 부부가 공동으로 입양하는 것이 원칙이고 미성년자만 될 수 있음(제908조의2)":"친양자는 3년 이상 혼인한 부부가 함께 입양하는 것이 원칙이고, 미성년자만 친양자가 될 수 있습니다.","친양자입양관계증명서는 친양자가 성년이 되어 신청하는 경우, 혼인당사자가 민법 제809조의 친족관계를 파악하려는 경우, 법원 또는 검사의 사실조회촉탁이나 수사기관의 문서 신청이 있는 경우 등에만 청구할 수 있음(2026. 8. 4. 개정 법 제14조 제2항)":"친양자입양관계증명서는 친양자가 성년이 되어 신청하거나 법원·수사기관이 문서를 신청하는 등 제한된 경우에만 청구할 수 있습니다.","친족·동거자·사망장소를 관리하는 사람과 사망장소의 동장이나 통·이장도 신고 가능(가족관계등록법 제85조)":"친족, 동거자, 사망장소 관리자와 사망장소의 동장이나 통·이장도 사망신고를 할 수 있습니다.","친족법이나 상속법상 중대한 영향을 미치는 사항은 확정판결로 정정하는 것이 원칙":"친족법이나 상속법상 큰 영향이 있는 사항은 확정판결을 받아 정정하는 것이 원칙입니다.","침탈자의 특별승계인에게는 그가 악의일 때에만 청구 가능(제204조 제2항)":"침탈자의 특별승계인에게는 그 승계인이 악의일 때만 점유회수를 청구할 수 있습니다.","타인 토지를 매수해 점유했다는 것만으로는 추정이 깨지지 않고, 자기 소유 부동산의 점유는 취득시효의 기초가 아님":"남의 토지를 샀다는 이유만으로 추정이 깨지지는 않으며, 자기 소유 부동산의 점유는 취득시효의 바탕이 아닙니다.","탈퇴 당시 재산 상태로 계산(제719조)":"탈퇴한 조합원과의 정산은 탈퇴 당시의 조합재산 상태를 기준으로 계산합니다.","태아는 상속순위에 관해 이미 출생한 것으로 보므로 대습상속과 유류분권도 인정":"상속순위에서는 태아도 이미 태어난 것으로 보아 대습상속과 유류분권을 갖습니다.","토지를 인도받은 매수인과 그에게서 다시 산 사람은 점유·사용할 권리가 있음":"토지를 넘겨받은 매수인과 그 전매수인은 그 땅을 쓸 정당한 권리를 갖습니다.","토지소유자는 건물소유자에게 퇴거를 청구할 수 없음":"토지소유자가 건물소유자에게 건물에서 나가라는 퇴거를 청구할 수는 없습니다.","토지소유자의 승낙 없이 20년간 평온·공연하게 분묘 기지를 점유하면 분묘기지권을 시효취득한다는 관습은 장사법 시행일인 2001. 1. 13. 전에 설치된 분묘에 대해 지금도 유지":"2001. 1. 13. 전에 설치된 분묘에는 승낙 없이 20년간 평온·공연히 점유하면 분묘기지권을 시효취득한다는 관습이 지금도 통합니다.","토지에만 저당권을 설정한 뒤 건물을 헐고 다시 지은 경우에는 성립하지만 토지와 건물에 공동저당을 설정한 뒤 건물을 헐고 새로 지었다면 신축건물에 같은 순위의 공동저당을 설정해 주는 등의 사정이 없는 한 성립하지 않음":"토지에만 저당권을 설정한 뒤 건물을 새로 지으면 성립하나, 공동저당을 설정한 뒤 신축하면 특별한 사정이 없는 한 성립하지 않습니다.","통정허위표시는 무효, 선의의 제3자에게 대항 불가이고 선의로 추정(제108조)":"통정허위표시는 무효이지만 선의의 제3자에게는 무효를 주장할 수 없고, 제3자의 선의는 추정됩니다.","통지 당시 이미 상계할 원인이 있었으면 그 뒤 상계적상이 되어도 양수인에게 상계로 대항할 수 있음":"통지 당시 이미 상계할 원인이 있었다면 상계적상이 나중에 되어도 양수인에게 상계로 맞설 수 있습니다.","통지할 수 없거나 정정신청을 하는 사람이 없거나 시·읍·면의 장의 잘못이면":"통지할 수 없거나, 정정을 신청할 사람이 없거나, 시·읍·면의 장의 잘못인 경우를 가리킵니다.","특약이 있는 채권도 전부명령으로 이전되고, 채무자가 무효인 양도를 사후 승낙하면 소급하지 않고 승낙한 때부터 유효":"양도금지 특약이 있어도 전부명령으로 이전되고, 무효인 양도를 사후에 승낙하면 소급 없이 승낙 때부터 유효합니다.","특정증명서는 가족관계증명서, 기본증명서, 혼인관계증명서에 대해서만 발급(규칙 제21조의2 제1항)":"특정증명서는 가족관계증명서, 기본증명서, 혼인관계증명서에 대해서만 발급합니다.","특정채권 보전이나 보증금반환채권 양수인이 임차인 대신 명도를 구하는 경우에는 채무자의 무자력이 필요 없음":"특정채권 보전의 경우나 보증금반환채권 양수인이 임차인을 대신해 명도를 구할 때는 채무자의 무자력이 요건이 아닙니다.","판결로만 정정할 수 있는 사항을 허가로 정정했다면 적법한 정정의 효력 없음":"판결로만 고칠 수 있는 사항을 허가로 고쳤다면 그 정정은 효력이 없습니다.","판결로 주채무가 10년으로 늘어나도 보증채무까지 늘어나지 않음":"판결로 주채무의 시효기간이 늘어나도 보증인의 시효기간은 그대로입니다.","판결로 주채무 시효가 10년이 되어도 보증채무 시효까지 늘어나지 않고, 보증채무 자체의 지연손해금은 보증한도액과 별도":"주채무 시효가 판결로 10년이 돼도 보증채무 시효는 불변이며, 보증채무의 지연손해금은 보증한도액과 별개로 셉니다.","폐쇄된 등록부도 부활 없이 정정":"이미 폐쇄된 등록부도 부활시키지 않고 그대로 정정할 수 있습니다.","표의자에게 중대한 과실이 있으면 취소 불가(제109조 제1항)":"표의자가 큰 부주의로 착오에 빠졌다면 취소가 막히며, 근거는 제109조 제1항입니다.","표현대리가 성립하는 범위를 넘은 행위에는 적용 가능(제129조, 제126조)":"표현대리가 성립하는 범위를 넘어선 행위에도 표현대리 규정을 적용해 볼 수 있습니다.","표현대리가 성립하면 상대방에게 과실이 있어도 과실상계로 본인의 책임을 줄이지 못함":"표현대리에서 상대방이 부주의했더라도 본인의 책임을 과실상계로 깎지는 않습니다.","피보전채권은 사해행위 전에 성립해야 하지만 그 당시 채권 성립의 기초 법률관계가 있고 가까운 장래 채권이 성립할 고도의 개연성이 있었으며 실제로 성립했다면 예외로 인정":"피보전채권은 사해행위 전 성립이 원칙이나 기초 법률관계와 고도의 개연성이 있고 실제 성립했다면 예외로 봅니다.","피보전채권의 기한 전에는 법원의 허가가 있어야 대위할 수 있고 보전행위는 예외(제404조 제2항)":"피보전채권의 변제기 전에는 법원 허가가 있어야 대위할 수 있고 보전행위는 허가 없이 가능합니다.","피해자가 직무에 관한 행위가 아님을 알았거나 중대한 과실로 몰랐으면 법인은 책임 없음":"직무 밖 행위임을 피해자가 알았거나 큰 부주의로 놓쳤다면 법인이 면책됩니다.","피해자 과실과 이득이 함께 있으면 과실상계를 먼저 하고 손익상계를 하며 사고 뒤에도 같은 보수를 받는다는 사정이나 주변 지가 상승은 공제하지 않음":"피해자 과실과 이득이 모두 있으면 과실상계를 먼저 한 뒤 손익상계를 하며, 주변 지가 상승 같은 사정은 공제하지 않습니다.","필요비·유익비 상환청구권은 점유물을 반환하거나 반환을 청구받은 때 생김":"필요비와 유익비의 상환청구권은 점유물을 돌려주거나 반환을 청구받은 때 생깁니다.","하자가 사고의 공동원인 중 하나이면 충분해 다른 원인으로 난 화재가 하자로 확산된 경우도 책임이 있고, 이 규정이 시공자의 제750조 책임을 배제하지 않음":"하자가 사고의 공동원인 중 하나이기만 해도 책임이 있고, 이 규정이 시공자의 제750조 책임을 배제하지는 않습니다.","하자란 통상 갖춰야 할 안전성을 갖추지 못한 상태로, 이용 과정에서 제3자에게 참을 한도를 넘는 피해를 주는 경우도 포함":"하자는 통상 갖춰야 할 안전성이 없는 상태를 뜻하며, 이용 중 제3자에게 참을 한도를 넘는 피해를 주는 경우도 포함합니다.","한국에서 혼인할 때 당사자 한쪽이 한국인이면 한국법 방식을 따라야 함":"한국에서 혼인하면서 한쪽이 한국인이라면 혼인 방식은 한국법을 따라야 합니다.","한국인과 외국인의 혼인신고를 받으면 한국인 등록부에 혼인사유만 기록":"한국인과 외국인이 혼인신고를 하면 한국인의 등록부에만 혼인사유를 적습니다.","한정승인을 하면 상속채권자는 상속인의 고유재산에 집행할 수 없지만 한정승인자에게서 상속재산에 담보권을 취득한 사람보다 우선하지도 못함":"한정승인이 되면 상속채권자는 상속인의 고유재산에 집행하지 못하고, 한정승인자로부터 담보권을 얻은 사람보다 앞서지도 못합니다.","합유물의 처분·변경과 합유지분 처분에는 전원의 동의가 필요하고 보존행위는 각자 함(제272조, 제273조)":"합유물과 합유지분을 처분하거나 바꾸려면 합유자 전원의 동의가 필요하고, 보존행위는 각자 할 수 있습니다.","합의해제·해지에는 손해배상 특약이나 유보가 없는 한 채무불이행 손해배상 청구 불가":"합의해제나 합의해지에서는 손해배상 특약이나 유보가 없으면 채무불이행으로 인한 손해배상을 청구하지 못합니다.","해제로 보호되는 제3자는 해제 전에 새 이해관계를 맺고 등기·인도 등으로 완전한 권리를 취득한 사람(제548조 제1항 단서)":"해제 전에 새 이해관계를 맺고 등기·인도로 완전한 권리를 얻은 사람만 해제에서 보호받는 제3자입니다.","해제 전에 매수인에게서 주택을 임차해 대항요건을 갖춘 임차인은 보호":"해제 전에 매수인으로부터 주택을 빌려 대항요건을 갖춘 임차인은 해제의 영향에서 보호됩니다.","행사는 재판 밖에서 해당 증여·유증을 지정해 의사표시하면 되고 목적물을 특정할 필요가 없으며 행사상 일신전속권이라 확정적 행사 의사가 없으면 채권자대위의 목적이 되지 않음":"재판 밖에서 증여·유증을 지정해 의사표시를 하면 행사가 되며 목적물을 특정할 필요가 없고, 확정적 행사 의사가 없으면 대위의 목적도 아닙니다.","허가결정에 따른 정정신청을 받으면 성별란을 정정":"성별정정 허가결정에 따른 신청을 받으면 등록부의 성별란을 고칩니다.","허가서 등본을 받은 날부터 1개월 안에 신고(가족관계등록법 제99조 제1항)":"개명 허가를 받았다면 허가서 등본을 받은 날부터 1개월 안에 신고해야 합니다.","허가 재판서 등본을 받은 날부터 1개월 안에 정정을 신청(가족관계등록법 제106조)":"허가 재판서 등본을 받은 날부터 1개월 안에 정정을 신청해야 합니다.","허위 출생신고로 기록된 친생자관계를 양친자관계로 고치려면 양친자관계존재확인 판결 필요":"허위 출생신고에 따른 친생자관계 기록을 양친자관계로 바꾸려면 양친자관계존재확인 판결이 있어야 합니다.","현재 혼인 중인지, 미성년 자녀가 있는지도 조사 가능":"현재 혼인 중인지, 미성년 자녀가 있는지도 법원이 조사할 수 있는 사항입니다.","현행 제1004조의2는 부양의무를 중대하게 위반하거나 중대한 범죄·심히 부당한 대우를 한 상속인에 대해 피상속인이 공정증서 유언으로 상속권 상실 의사를 표시하거나, 유언이 없으면 공동상속인이 그 사람이 상속인이 된 것을 안 날부터 6개월 안에 가정법원에 상속권 상실을 청구할 수 있게 하고, 선고가 확정되면 상속개시 때로 소급해 상속권을 잃음":"부양의무를 크게 어기거나 중대한 범죄를 저지른 상속인은 피상속인의 공정증서 유언이나 공동상속인의 6개월 내 청구로 상속권을 잃습니다.","협의가 안 되면 상속재산분할심판을 청구해야 하고 개별 재산에 공유물분할의 소를 낼 수 없으며 공동상속인 일부의 한정승인 청산 중에도 분할청구를 할 수 있음":"협의가 깨지면 상속재산분할심판을 청구해야 하고 개별 재산의 공유물분할의 소는 불가하며, 일부 상속인의 한정승인 청산 중에도 분할청구가 됩니다.","협의는 그 부부 사이의 모든 자녀에게 미쳐 자녀마다 달리 정한 협의서는 수리하지 않음":"협의의 효력은 부부 사이 모든 자녀에게 미치므로 자녀별로 다르게 적은 협의서는 받아 주지 않습니다.","협의이혼 부부의 포태 중 자녀 친권자지정 신고는 이혼신고와 함께 수리할 수 없음":"협의이혼 부부가 태아의 친권자를 정하는 신고는 이혼신고와 한꺼번에 처리하지 못합니다.","협의이혼은 등록기준지나 주소지 관할 가정법원의 확인을 받아 신고":"협의이혼은 가정법원이 이혼 의사를 확인해 주어야 하며, 법원은 등록기준지나 주소지 관할입니다.","협의이혼은 일시적으로라도 법률상 부부관계를 해소하려는 합의가 있으면 다른 목적이 있어도 무효가 아님":"잠깐이라도 법률상 부부관계를 끝내기로 합의했다면 다른 속셈이 있어도 협의이혼은 무효가 아닙니다.","협의이혼을 전제로 한 분할 협의는 재판상 이혼이 되면 효력이 없고, 이혼 전에 분할청구권을 포기하는 서면은 원칙적으로 허용되지 않는 사전포기일 뿐":"협의이혼 전제의 분할 합의는 재판상 이혼 시 효력이 없고, 이혼 전 분할청구권 포기 서면은 원칙적으로 사전포기라 허용되지 않습니다.","형사고소·기소는 재판상 청구가 아니고, 공유자 1인의 보존행위 소송은 그 공유자에게만 중단 효력":"형사고소나 기소는 재판상 청구가 아니며, 공유자 한 명의 보존행위 소송은 그 사람에게만 중단 효력이 있습니다.","형사사건 성공보수약정과 통상 수준을 넘는 증언 대가 약정은 무효":"형사사건 성공보수 약정과 보통을 넘는 증언 대가 약정은 효력이 없습니다.","혼인신고는 당사자 쌍방과 성년자인 증인 2인이 연서한 서면으로 함(민법 제812조 제2항)":"혼인신고는 당사자 쌍방과 성년인 증인 2인이 연서한 서면으로 해야 합니다.","혼인신고서와 같은 날 접수되어 선후를 알 수 없으면 수리불가신고서가 먼저 접수된 것으로 봄":"혼인신고서와 같은 날 들어와 순서를 알 수 없으면 수리불가신고서가 앞선 것으로 처리합니다.","혼인신고수리불가신고는 횟수 제한이 없고 6개월 범위에서 취급기간을 정함":"혼인신고수리불가신고는 횟수에 제한이 없고, 취급기간은 6개월 범위에서 정합니다.","혼인의 실질적 요건은 각자의 본국법에 따름":"혼인이 성립하기 위한 실질 요건은 각 당사자의 본국법을 적용합니다.","혼인 중 제3자에게 진 채무는 원칙적으로 각자의 채무이지만 공동재산의 형성·유지에 수반한 채무는 청산 대상":"혼인 중 제3자에게 진 빚은 각자 몫이 원칙이나, 공동재산을 만들고 지키며 진 빚은 분할로 정산합니다.","혼인 중 출생자는 부 또는 모가 신고, 혼인 외 출생자는 모가 신고(가족관계등록법 제46조)":"혼인 중 출생자는 부 또는 모가, 혼인 외 출생자는 모가 신고해야 합니다.","혼인처럼 신고로 효력이 생기는 행위는 기록한 뒤 실체상 흠을 발견해도 이 직권 정정으로 고칠 수 없음":"혼인같이 신고로 효력이 생기는 행위는 기록 후 실체상 흠이 발견되어도 직권 정정으로는 바로잡지 못합니다.","확인서등본을 받은 날부터 3개월 안에 신고, 지나면 확인은 효력 상실(가족관계등록법 제75조 제2항·제3항)":"확인서등본을 받은 날부터 3개월 안에 신고해야 하며, 지나면 확인이 효력을 잃습니다.","확인서등본을 첨부하면 증인 2인의 연서가 있는 것으로 봄(가족관계등록법 제76조)":"확인서등본을 첨부하면 증인 2인이 연서한 것으로 취급합니다.","확인신청은 부부가 함께 출석해서 하고 대리인은 불가, 신고서는 한쪽이 제출해도 됨":"확인을 신청할 때는 부부가 함께 나가야 하고 대리는 안 되나, 신고서 제출은 한 사람이 해도 됩니다.","확장할 뜻을 밝히고 실제로 확장하면 확장된 부분도 소 제기 시로 소급":"청구를 늘리겠다고 밝히고 실제로 늘리면 늘어난 부분도 처음 소를 제기한 때로 소급해 중단됩니다.","확정 뒤 새로 생긴 원본은 담보되지 않지만 확정 전 원본에서 확정 뒤 생긴 이자·지연손해금은 최고액 안에서 담보되고, 존속기간 정함이 없으면 설정자나 제3취득자가 언제든 해지해 확정시킬 수 있음":"확정 뒤 새 원본은 담보되지 않지만 확정 전 원본의 이자·지연손해금은 최고액 안에서 담보되고, 존속기간이 없으면 해지해 확정시킬 수 있습니다.","확정 전에 채권 일부를 대위변제해도 근저당권은 대위변제자에게 이전하지 않고, 확정 뒤에는 부기등기와 관계없이 대위변제 범위에서 당연히 이전":"확정 전에 일부를 대위변제하면 근저당권이 이전하지 않고, 확정 뒤에는 대위변제한 범위만큼 부기등기와 상관없이 당연히 이전합니다.","회복등기 전이라도 말소된 등기의 명의인이 적법한 권리자로 추정":"말소된 등기라도 회복등기를 하기 전부터 그 명의인을 권리자로 추정합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
